export enum UserRole {
  SUPERADMIN = 'SUPERADMIN', // Leandro - Acceso Total
  ADMIN = 'ADMIN',           // Evelin - Gestión Central
  HEAD = 'HEAD',            // Jefaturas - Gestión de Área
  ANALYST = 'ANALYST'       // Analistas - Ejecución Técnica
}

export enum Area {
  CONTABILIDAD = 'Contabilidad',
  RRHH = 'RRHH',
  ACREDITACION = 'Acreditación',
  FINANZAS = 'Finanzas'
}

export enum Status {
  RECIBIDO = 'Recibido',      // Bandeja Central (Admin)
  DERIVACION = 'En Derivación', // En bandeja de Jefatura
  EJECUCION = 'En Ejecución',   // Asignado a Analista
  FINALIZADO = 'Finalizado'     // Cumplido (Auditoría)
}

export enum Priority {
  HIGH = 'Alta',
  MEDIUM = 'Media',
  LOW = 'Baja'
}

export type UserStatus = 'ACTIVE' | 'INACTIVE';

export interface User {
  id: string;
  name: string;
  email?: string;
  status?: UserStatus;
  joinedAt?: string;
  role: UserRole;
  area?: Area; 
  password?: string;
}

export interface LogEntry {
  id: string;
  timestamp: string;
  message: string;
  actor: string;
  role: UserRole;
}

export interface RequestCard {
  id: string;
  title: string;
  detail: string;
  requester: string;
  area: Area;
  status: Status;
  priority: Priority;
  responsibleHead: string; 
  assignedAnalyst?: string; 
  logs: LogEntry[];
  createdAt: string;
  finishedAt?: string;
  isReturned?: boolean; 
  lastUpdated?: string;
}

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { User, RequestCard, Status, Priority, Area, UserRole, LogEntry } from '../types';
import { AREA_HEADS } from '../constants';
import { db } from '../services/storage';

interface SisreqContextType {
  currentUser: User | null;
  users: User[];
  isAuthenticated: boolean;
  isLoading: boolean;
  login: (user: User) => void;
  logout: () => void;
  setCurrentUser: (user: User) => void;
  updateUser: (updatedUser: User) => Promise<void>;
  addUser: (name: string, email: string, role: UserRole, password: string, area?: Area) => Promise<void>;

  requests: RequestCard[];
  selectedRequestId: string | null;
  setSelectedRequestId: (id: string | null) => void;
  addRequest: (title: string, detail: string, area: Area, priority: Priority, requester: string) => Promise<void>;
  updateStatus: (id: string, newStatus: Status) => Promise<void>;
  deleteRequest: (id: string) => Promise<void>;
  returnRequest: (id: string, reason: string) => Promise<void>;
  assignAnalyst: (id: string, analystName: string) => Promise<void>;
  addLog: (id: string, message: string) => Promise<void>;
  updateRequestDetails: (id: string, title: string, detail: string) => Promise<void>;

  viewMode: 'work' | 'superadmin';
  setViewMode: (mode: 'work' | 'superadmin') => void;

  activeRole: UserRole | null;
  setActiveRole: (role: UserRole) => void;

  globalFilterArea: Area | 'ALL';
  setGlobalFilterArea: (area: Area | 'ALL') => void;

  canUserTransition: (request: RequestCard, targetStatus: Status) => { allowed: boolean; reason?: string };
}

const SisreqContext = createContext<SisreqContextType | undefined>(undefined);

const generateId = (prefix: string) => `${prefix}-${Math.random().toString(36).substring(2, 8)}-${Date.now().toString(36)}`;

export const SisreqProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null); 
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [requests, setRequests] = useState<RequestCard[]>([]);
  const [selectedRequestId, setSelectedRequestId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'work' | 'superadmin'>('work');
  const [isLoading, setIsLoading] = useState(true);
  const [globalFilterArea, setGlobalFilterArea] = useState<Area | 'ALL'>('ALL');
  const [activeRole, setActiveRole] = useState<UserRole | null>(null);

  useEffect(() => {
    const initApp = async () => {
        try {
            await db.init();
            const [loadedRequests, loadedUsers] = await Promise.all([
                db.getRequests(),
                db.getUsers()
            ]);
            setRequests(loadedRequests.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()));
            setUsers(loadedUsers);
        } catch (error) {
            console.error("Critical Failure in SISREQ Core:", error);
        } finally {
            setIsLoading(false);
        }
    };
    initApp();
  }, []);

  const login = (user: User) => {
    const foundUser = users.find(u => u.id === user.id) || user;
    setCurrentUser(foundUser);
    setIsAuthenticated(true);
    setViewMode('work');
    setGlobalFilterArea('ALL');
    setActiveRole(foundUser.role);
  };

  const logout = () => {
    setIsAuthenticated(false);
    setSelectedRequestId(null);
    setCurrentUser(null);
    setActiveRole(null);
  };

  const updateUser = useCallback(async (updatedUser: User) => {
    await db.saveUser(updatedUser);
    setUsers(prev => prev.map(u => u.id === updatedUser.id ? updatedUser : u));
    if (currentUser && currentUser.id === updatedUser.id) {
        setCurrentUser(updatedUser);
    }
  }, [currentUser]);

  const addUser = useCallback(async (name: string, email: string, role: UserRole, password: string, area?: Area) => {
    const newUser: User = {
        id: generateId('u'),
        name,
        email,
        role,
        area,
        password,
        status: 'ACTIVE',
        joinedAt: new Date().toISOString()
    };
    await db.saveUser(newUser);
    setUsers(prev => [...prev, newUser]);
  }, []);

  const canUserTransition = useCallback((request: RequestCard, targetStatus: Status): { allowed: boolean; reason?: string } => {
    if (!currentUser || !activeRole) return { allowed: false, reason: 'No hay una sesión activa.' };
    if (request.status === targetStatus) return { allowed: true };

    // SuperAdmin Bypass: Regla de Auditoría Superior
    if (activeRole === UserRole.SUPERADMIN) return { allowed: true };

    // Protección de Tickets Finalizados
    if (request.status === Status.FINALIZADO && targetStatus !== Status.FINALIZADO) {
        return { allowed: false, reason: 'Solo un SuperAdmin puede reabrir requerimientos finalizados.' };
    }

    switch (activeRole) {
        case UserRole.ADMIN:
            // Admin Central solo deriva de Recibido a Derivación
            if (request.status === Status.RECIBIDO && targetStatus === Status.DERIVACION) return { allowed: true };
            return { allowed: false, reason: 'Como Admin Central, su facultad termina al derivar el ticket al área técnica.' };

        case UserRole.HEAD:
            if (request.area !== currentUser.area) return { allowed: false, reason: 'Ticket fuera de su jurisdicción técnica.' };

            // Derivación -> Ejecución (Requiere Analista Asignado)
            if (request.status === Status.DERIVACION && targetStatus === Status.EJECUCION) {
                if (!request.assignedAnalyst) return { allowed: false, reason: 'Debe asignar un responsable técnico antes de iniciar.' };
                return { allowed: true };
            }
            // Ejecución -> Finalizado
            if (request.status === Status.EJECUCION && targetStatus === Status.FINALIZADO) return { allowed: true };

            return { allowed: false, reason: 'La jefatura no puede realizar esta transición en el estado actual.' };

        case UserRole.ANALYST:
            if (request.area !== currentUser.area) return { allowed: false, reason: 'Acceso denegado: Ticket de otra área.' };
            if (request.status === Status.EJECUCION && targetStatus === Status.FINALIZADO) return { allowed: true };
            return { allowed: false, reason: 'Los analistas solo pueden finalizar tickets que ya están en ejecución.' };

        default:
            return { allowed: false, reason: 'Rol no autorizado para cambios de fase.' };
    }
  }, [currentUser, activeRole]);

  const addRequest = useCallback(async (title: string, detail: string, area: Area, priority: Priority, requester: string) => {
    if (!currentUser || !activeRole) return;
    const newRequest: RequestCard = {
      id: generateId('req'),
      title,
      detail,
      area,
      status: Status.RECIBIDO,
      priority,
      requester,
      responsibleHead: AREA_HEADS[area],
      createdAt: new Date().toISOString(),
      logs: [{
        id: generateId('log'),
        timestamp: new Date().toISOString(),
        message: `Apertura de requerimiento SISREQ`,
        actor: currentUser.name,
        role: activeRole
      }]
    };
    await db.saveRequest(newRequest);
    setRequests(prev => [newRequest, ...prev]);
  }, [currentUser, activeRole]);

  const updateStatus = useCallback(async (id: string, newStatus: Status) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const { allowed, reason } = canUserTransition(req, newStatus);
    if (!allowed) throw new Error(reason);

    const isReopening = req.status === Status.FINALIZADO && newStatus !== Status.FINALIZADO;
    const isReturningToSource = newStatus === Status.RECIBIDO;

    const updatedReq: RequestCard = {
        ...req,
        status: newStatus,
        finishedAt: newStatus === Status.FINALIZADO ? new Date().toISOString() : (isReopening ? undefined : req.finishedAt),
        isReturned: isReturningToSource ? true : (newStatus === Status.DERIVACION ? false : req.isReturned),
        assignedAnalyst: isReturningToSource ? undefined : req.assignedAnalyst,
        lastUpdated: new Date().toISOString(),
        logs: [
          ...req.logs,
          {
            id: generateId('log'),
            timestamp: new Date().toISOString(),
            message: `Transición de Fase: ${newStatus}`,
            actor: currentUser.name,
            role: activeRole
          }
        ]
    };

    await db.saveRequest(updatedReq);
    setRequests(prev => prev.map(r => r.id === id ? updatedReq : r));
  }, [currentUser, requests, activeRole, canUserTransition]);

  const returnRequest = useCallback(async (id: string, reason: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    if (activeRole !== UserRole.HEAD && activeRole !== UserRole.SUPERADMIN) {
        throw new Error("Solo las Jefaturas o SuperAdmin pueden devolver tickets a la bandeja central.");
    }

    const updatedReq: RequestCard = {
        ...req,
        status: Status.RECIBIDO,
        isReturned: true,
        assignedAnalyst: undefined, 
        lastUpdated: new Date().toISOString(),
        logs: [
          ...req.logs,
          {
            id: generateId('log'),
            timestamp: new Date().toISOString(),
            message: `DEVOLUCIÓN A CENTRAL: ${reason}`,
            actor: currentUser.name,
            role: activeRole
          }
        ]
    };
    await db.saveRequest(updatedReq);
    setRequests(prev => prev.map(r => r.id === id ? updatedReq : r));
  }, [currentUser, requests, activeRole]);

  const assignAnalyst = useCallback(async (id: string, analystName: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const updatedReq: RequestCard = {
        ...req,
        assignedAnalyst: analystName,
        lastUpdated: new Date().toISOString(),
        logs: [
          ...req.logs,
          {
            id: generateId('log'),
            timestamp: new Date().toISOString(),
            message: `Asignación de Responsable Técnico: ${analystName}`,
            actor: currentUser.name,
            role: activeRole
          }
        ]
    };
    await db.saveRequest(updatedReq);
    setRequests(prev => prev.map(r => r.id === id ? updatedReq : r));
  }, [currentUser, requests, activeRole]);

  const deleteRequest = useCallback(async (id: string) => {
    if (activeRole !== UserRole.SUPERADMIN) return;
    await db.deleteRequest(id);
    setRequests(prev => prev.filter(r => r.id !== id));
  }, [activeRole]);

  const addLog = useCallback(async (id: string, message: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;
    const updatedReq: RequestCard = {
        ...req,
        lastUpdated: new Date().toISOString(),
        logs: [...req.logs, { 
            id: generateId('log'), 
            timestamp: new Date().toISOString(), 
            message, 
            actor: currentUser.name, 
            role: activeRole 
        }]
    };
    await db.saveRequest(updatedReq);
    setRequests(prev => prev.map(r => r.id === id ? updatedReq : r));
  }, [currentUser, requests, activeRole]);

  const updateRequestDetails = useCallback(async (id: string, title: string, detail: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;
    const updatedReq: RequestCard = { 
        ...req, 
        title, 
        detail,
        lastUpdated: new Date().toISOString(),
        logs: [...req.logs, { 
            id: generateId('log'), 
            timestamp: new Date().toISOString(), 
            message: 'Edición de metadatos del requerimiento', 
            actor: currentUser.name, 
            role: activeRole 
        }]
    };
    await db.saveRequest(updatedReq);
    setRequests(prev => prev.map(r => r.id === id ? updatedReq : r));
  }, [requests, currentUser, activeRole]);

  return (
    <SisreqContext.Provider value={{
      currentUser,
      users,
      isAuthenticated,
      isLoading,
      login,
      logout,
      setCurrentUser,
      updateUser,
      addUser,
      requests,
      selectedRequestId,
      setSelectedRequestId,
      addRequest,
      updateStatus,
      deleteRequest,
      returnRequest,
      assignAnalyst,
      addLog,
      updateRequestDetails,
      viewMode,
      setViewMode,
      activeRole,
      setActiveRole,
      globalFilterArea,
      setGlobalFilterArea,
      canUserTransition
    }}>
      {children}
    </SisreqContext.Provider>
  );
};

export const useSisreq = () => {
  const context = useContext(SisreqContext);
  if (context === undefined) throw new Error('useSisreq must be used within a SisreqProvider');
  return context;
};

import React, { useState, useEffect } from 'react';
import { RequestCard as RequestCardType, UserRole, Status } from '../types';
import { useSisreq } from '../context/SisreqContext';
import { PRIORITY_STYLES } from '../constants';
import { User as UserIcon, GripVertical, MapPin, ChevronUp, ChevronDown, Clock, Hash, Building2, AlertCircle } from 'lucide-react';

interface Props {
  data: RequestCardType;
}

export const RequestCard: React.FC<Props> = ({ data }) => {
  const { currentUser, setSelectedRequestId, activeRole } = useSisreq();
  const [isMinimized, setIsMinimized] = useState(data.status === Status.FINALIZADO);

  useEffect(() => {
    if (data.status === Status.FINALIZADO) {
        setIsMinimized(true);
    }
  }, [data.status]);

  const isDraggable = () => {
    if (!currentUser || !activeRole) return false;
    if (activeRole === UserRole.SUPERADMIN) return true;

    // Admin Central mueve lo Recibido
    if (activeRole === UserRole.ADMIN && data.status === Status.RECIBIDO) return true;

    // Personal de área mueve sus propios tickets
    if (data.area === currentUser.area) {
        // Jefatura mueve de Derivación (si tiene analista) o de Ejecución
        if (activeRole === UserRole.HEAD) {
            if (data.status === Status.DERIVACION && !!data.assignedAnalyst) return true;
            if (data.status === Status.EJECUCION) return true;
        }
        // Analista mueve de Ejecución a Finalizado
        if (activeRole === UserRole.ANALYST && data.status === Status.EJECUCION) return true;
    }
    return false;
  };

  const handleDragStart = (e: React.DragEvent) => {
    if (!isDraggable()) {
        e.preventDefault();
        return;
    }
    e.dataTransfer.setData('requestId', data.id);
    e.dataTransfer.effectAllowed = 'move';

    // Feedback visual de arrastre
    const dragGhost = e.currentTarget as HTMLElement;
    dragGhost.style.opacity = '0.5';
    setTimeout(() => {
        if (dragGhost) dragGhost.style.opacity = '1';
    }, 0);
  };

  const handleCardClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    setSelectedRequestId(data.id);
  };

  const getAccentColor = (status: Status) => {
    switch (status) {
        case Status.RECIBIDO: return 'border-indigo-400';
        case Status.DERIVACION: return 'border-orange-400';
        case Status.EJECUCION: return 'border-amber-400';
        case Status.FINALIZADO: return 'border-emerald-400';
        default: return 'border-slate-300';
    }
  };

  return (
    <div 
        draggable={isDraggable()}
        onDragStart={handleDragStart}
        onClick={handleCardClick}
        className={`
            bg-white rounded-xl mb-2.5 relative group
            transition-all duration-200 ease-out
            shadow-[0_2px_8px_-4px_rgba(0,0,0,0.05)] hover:shadow-[0_12px_24px_-8px_rgba(0,0,0,0.12)]
            border border-slate-100
            border-l-[4px]
            cursor-pointer flex flex-col
            ${getAccentColor(data.status)}
            ${isDraggable() ? 'hover:bg-indigo-50/5' : 'cursor-default'}
            ${isMinimized ? 'h-[56px] py-2 px-4' : 'min-h-[175px] p-4'}
        `}
    >
      <div className={`flex justify-between items-center shrink-0 ${isMinimized ? '' : 'mb-2.5'}`}>
        <div className="flex items-center gap-2">
            {isDraggable() && !isMinimized && (
                <div onMouseDown={(e) => e.stopPropagation()} className="p-0.5 -ml-1 text-slate-200 group-hover:text-indigo-400 cursor-grab active:cursor-grabbing">
                    <GripVertical size={12} />
                </div>
            )}
            <div className="flex items-center gap-1.5">
                <span className="flex items-center gap-0.5 font-mono text-[9px] text-slate-400 font-bold uppercase tracking-tight">
                    <Hash size={9} className="opacity-30" /> {data.id.split('-')[1].substring(0, 6)}
                </span>
                {data.isReturned && !isMinimized && (
                     <span className="text-[8px] bg-red-600 text-white px-1.5 py-0.5 rounded font-black tracking-tight flex items-center gap-1 shadow-sm uppercase">
                        <AlertCircle size={8}/> REVISIÓN
                     </span>
                )}
            </div>
        </div>

        <div className="flex items-center gap-1.5">
           {!isMinimized && (
             <span className={`text-[8px] font-black px-1.5 py-0.5 rounded border shadow-none transition-colors uppercase tracking-tight ${PRIORITY_STYLES[data.priority]}`}>
               {data.priority}
             </span>
           )}
           <button 
                onClick={(e) => { e.stopPropagation(); setIsMinimized(!isMinimized); }}
                className="p-1 text-slate-300 hover:text-slate-500 hover:bg-slate-50 rounded transition-all"
           >
               {isMinimized ? <ChevronDown size={14}/> : <ChevronUp size={14}/>}
           </button>
        </div>
      </div>

      <div className={`flex-1 overflow-hidden ${isMinimized ? 'flex items-center gap-3 pr-8' : 'flex flex-col'}`}>
        <h3 className={`font-bold text-slate-700 leading-snug tracking-tight group-hover:text-indigo-600 transition-colors 
            ${isMinimized ? 'text-[11px] truncate flex-1' : 'text-[13px] mb-2 line-clamp-2'}`}>
            {data.title}
        </h3>

        {!isMinimized && (
            <div className="flex-1 bg-slate-50/50 p-2.5 rounded-lg border border-slate-100/50 mb-3 overflow-hidden">
                <p className="text-[11px] text-slate-400 leading-normal line-clamp-2 font-medium italic">
                    {data.detail}
                </p>
            </div>
        )}
      </div>

      {!isMinimized ? (
          <div className="mt-auto pt-2 border-t border-slate-100/60 flex flex-col gap-1.5 shrink-0">
             <div className="flex items-center justify-between">
                <div className="flex flex-col gap-0.5">
                    <div className="flex items-center gap-1.5 text-[9px] font-black text-indigo-500 uppercase tracking-tight">
                        <MapPin size={10} className="opacity-60" /> {data.area}
                    </div>
                    <div className="flex items-center gap-1.5 text-[9px] font-bold text-slate-400 uppercase tracking-tight max-w-[140px]">
                        <Building2 size={10} className="opacity-40" />
                        <span className="truncate">{data.requester}</span>
                    </div>
                </div>

                <div className="flex flex-col items-end gap-1">
                    {data.assignedAnalyst ? (
                        <div className="flex items-center gap-1 bg-indigo-50 text-indigo-600 px-1.5 py-0.5 rounded text-[8px] font-black border border-indigo-100 shadow-sm" title="Analista Responsable">
                            <UserIcon size={9} className="opacity-60" />
                            <span className="truncate max-w-[60px]">{data.assignedAnalyst.split(' ')[0]}</span>
                        </div>
                    ) : (
                        <div className="flex items-center gap-1 text-slate-300 font-mono text-[9px] font-bold">
                            <Clock size={10} className="opacity-40" />
                            {new Date(data.createdAt).toLocaleDateString(undefined, { day: '2-digit', month: '2-digit' })}
                        </div>
                    )}
                </div>
             </div>
          </div>
      ) : (
          <div className="absolute right-10 top-1/2 -translate-y-1/2 flex items-center gap-2 pointer-events-none opacity-40">
              <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{data.area}</span>
              <div className={`w-1.5 h-1.5 rounded-full ${data.status === Status.FINALIZADO ? 'bg-emerald-500' : 'bg-slate-300'}`}></div>
          </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { STATUS_BADGE_COLORS, PRIORITY_STYLES } from '../constants';
import { UserRole, Status, Priority } from '../types';
import { 
    X, Calendar, User, Building, AlertCircle, Clock, Tag, ArrowRight, 
    CheckCircle, Briefcase, Pencil, Save, Send, MessageSquare,
    RotateCcw, Sparkles, CheckCircle2, Circle, Eye, Hash, PlayCircle, Trash2,
    ShieldAlert, UserCheck, LayoutDashboard, History, ClipboardList, PenTool
} from 'lucide-react';

export const RequestDetailModal: React.FC = () => {
  const { 
    selectedRequestId, 
    setSelectedRequestId, 
    requests, 
    currentUser, 
    updateStatus, 
    deleteRequest,
    returnRequest, 
    assignAnalyst,
    updateRequestDetails,
    addLog,
    users,
    activeRole,
    canUserTransition
  } = useSisreq();

  const [returnReason, setReturnReason] = useState('');
  const [showReturnInput, setShowReturnInput] = useState(false);
  const [showAnalystSelect, setShowAnalystSelect] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editTitle, setEditTitle] = useState('');
  const [editDetail, setEditDetail] = useState('');
  const [newComment, setNewComment] = useState('');
  const [actionError, setActionError] = useState<string | null>(null);

  const data = requests.find(r => r.id === selectedRequestId);

  useEffect(() => {
     if (data) {
        setEditTitle(data.title);
        setEditDetail(data.detail);
        setIsEditing(false);
        setShowReturnInput(false);
        setShowAnalystSelect(false);
        setNewComment('');
        setActionError(null);
     }
  }, [selectedRequestId, data]);

  if (!selectedRequestId || !data || !currentUser) return null;

  const handleClose = () => setSelectedRequestId(null);
  const isFinalized = data.status === Status.FINALIZADO;

  const handleTransition = async (targetStatus: Status) => {
    setActionError(null);
    try {
        await updateStatus(data.id, targetStatus);
    } catch (e: any) {
        setActionError(e.message);
    }
  };

  const handleReturnSubmit = async () => {
    if (returnReason.trim()) {
      try {
        await returnRequest(data.id, returnReason);
        setShowReturnInput(false);
        setReturnReason('');
      } catch (e: any) {
        setActionError(e.message);
      }
    }
  };

  const handleAssignAnalyst = (analystName: string) => {
    assignAnalyst(data.id, analystName);
    setShowAnalystSelect(false);
  };

  const handleSaveChanges = async () => {
    if (editTitle.trim() && editDetail.trim()) {
        await updateRequestDetails(data.id, editTitle, editDetail);
        setIsEditing(false);
    }
  };

  const handleAddComment = async () => {
    if (newComment.trim()) {
        await addLog(data.id, `COMENTARIO: ${newComment}`);
        setNewComment('');
    }
  };

  const availableAssignees = users.filter(u => 
    (u.role === UserRole.ANALYST || u.role === UserRole.HEAD) && 
    u.area === data.area &&
    (u.status === 'ACTIVE' || !u.status)
  );

  const canDeriveUI = canUserTransition(data, Status.DERIVACION).allowed;
  const canExecuteUI = canUserTransition(data, Status.EJECUCION).allowed;
  const canFinalizeUI = canUserTransition(data, Status.FINALIZADO).allowed;
  const canEditUI = activeRole === UserRole.ADMIN || activeRole === UserRole.SUPERADMIN;

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-900/80 backdrop-blur-md transition-opacity" onClick={handleClose}></div>

      <div className={`relative bg-white rounded-[2.5rem] shadow-2xl w-full max-w-2xl max-h-[92vh] flex flex-col overflow-hidden animate-in fade-in zoom-in-95 duration-300 border border-slate-200 border-t-[12px] ${isFinalized ? 'border-emerald-500' : 'border-indigo-600'}`}>

        {/* Header Section */}
        <div className="bg-slate-50 border-b border-slate-100 px-8 py-6 flex justify-between items-center shrink-0">
          <div className="flex items-center gap-5 min-w-0">
             <div className={`p-3.5 rounded-2xl text-white shrink-0 shadow-lg ${isFinalized ? 'bg-emerald-600' : 'bg-slate-800'}`}>
                {isFinalized ? <CheckCircle2 size={24} strokeWidth={2.5}/> : <ClipboardList size={24} strokeWidth={2.5} />}
             </div>
             <div className="min-w-0">
                <div className="flex items-center gap-2 mb-1.5">
                    <span className={`px-3 py-0.5 rounded-lg text-[10px] font-black uppercase tracking-[0.15em] shadow-sm ring-1 ring-black/5 ${STATUS_BADGE_COLORS[data.status]}`}>
                        {data.status}
                    </span>
                    <span className="text-[10px] text-slate-400 font-mono font-black bg-white px-2 py-0.5 rounded border border-slate-100 flex items-center gap-1">
                        <Hash size={10} className="opacity-40"/>{data.id.split('-')[1].toUpperCase()}
                    </span>
                </div>
                {isEditing ? (
                    <input 
                        value={editTitle}
                        onChange={e => setEditTitle(e.target.value)}
                        className="text-xl font-black text-slate-900 w-full bg-white border-b-2 border-indigo-500 outline-none uppercase"
                    />
                ) : (
                    <h2 className="text-xl font-black text-slate-900 truncate uppercase tracking-tight">{data.title}</h2>
                )}
             </div>
          </div>
          <button onClick={handleClose} className="p-2.5 text-slate-300 hover:text-slate-900 hover:bg-white rounded-full transition-all border border-transparent hover:border-slate-100">
            <X size={24} />
          </button>
        </div>

        {/* Content Section */}
        <div className="flex-1 overflow-y-auto p-8 space-y-10 bg-white custom-scrollbar">

            {/* Descriptive Area */}
            <div className="space-y-3">
                <div className="flex items-center justify-between">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
                        <PenTool size={14} className="text-indigo-500"/> Memoria Descriptiva
                    </label>
                    {canEditUI && !isEditing && (
                        <button onClick={() => setIsEditing(true)} className="text-[10px] font-black text-indigo-600 uppercase hover:underline">Editar Información</button>
                    )}
                </div>
                {isEditing ? (
                    <textarea 
                        value={editDetail}
                        onChange={e => setEditDetail(e.target.value)}
                        className="w-full bg-slate-50 border-2 border-indigo-100 p-6 rounded-[2rem] text-sm text-slate-700 leading-relaxed outline-none min-h-[150px]"
                    />
                ) : (
                    <div className="bg-slate-50/50 p-6 rounded-[2rem] border border-slate-100 italic text-slate-600 text-sm leading-relaxed shadow-inner">
                        "{data.detail}"
                    </div>
                )}
                {isEditing && (
                    <div className="flex justify-end gap-3 pt-2">
                        <button onClick={() => setIsEditing(false)} className="px-4 py-2 text-[10px] font-bold text-slate-400 uppercase">Descartar</button>
                        <button onClick={handleSaveChanges} className="bg-indigo-600 text-white px-6 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg shadow-indigo-100 flex items-center gap-2">
                            <Save size={14}/> Guardar Cambios
                        </button>
                    </div>
                )}
            </div>

            {/* Context Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
