                                    <p className="text-[11px] text-slate-600 font-bold uppercase tracking-tight leading-relaxed">{log.message}</p>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        </div>

        {/* Footer Actions */}
        <div className="bg-white border-t border-slate-100 p-8 flex flex-col gap-4 shrink-0">
            {actionError && (
                <div className="bg-red-50 border border-red-100 p-4 rounded-2xl flex items-center gap-4 text-red-600 text-[11px] font-black uppercase tracking-widest animate-in slide-in-from-top-2">
                    <ShieldAlert size={18}/> {actionError}
                </div>
            )}

            <div className="flex justify-between items-center gap-4">
                <div className="flex items-center gap-2">
                    {activeRole === UserRole.SUPERADMIN && (
                        <button 
                            onClick={() => { if(confirm('¿ELIMINAR TICKET PERMANENTEMENTE?')) { deleteRequest(data.id); handleClose(); }}} 
                            className="p-3 text-red-400 hover:text-red-600 hover:bg-red-50 rounded-2xl transition-all border border-transparent hover:border-red-100"
                            title="Eliminar Requerimiento"
                        >
                            <Trash2 size={20}/>
                        </button>
                    )}

                    {(activeRole === UserRole.HEAD || activeRole === UserRole.SUPERADMIN) && data.status !== Status.RECIBIDO && data.status !== Status.FINALIZADO && (
                        <div className="flex items-center gap-2">
                            {showReturnInput ? (
                                <div className="flex items-center gap-2 bg-red-50 p-1.5 rounded-2xl border border-red-100 animate-in slide-in-from-left-4">
                                    <input 
                                        autoFocus
                                        value={returnReason}
                                        onChange={e => setReturnReason(e.target.value)}
                                        placeholder="Motivo de devolución..."
                                        className="bg-white border border-red-200 px-4 py-2 rounded-xl text-[10px] font-bold text-red-900 outline-none w-48"
                                    />
                                    <button onClick={handleReturnSubmit} className="bg-red-600 text-white px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest">Confirmar</button>
                                    <button onClick={() => setShowReturnInput(false)} className="p-2 text-red-400"><X size={16}/></button>
                                </div>
                            ) : (
                                <button 
                                    onClick={() => setShowReturnInput(true)} 
                                    className="px-6 py-3 rounded-2xl text-[10px] font-black text-red-600 border-2 border-red-100 hover:bg-red-50 transition-all uppercase tracking-widest flex items-center gap-2"
                                >
                                    <RotateCcw size={14} strokeWidth={3}/> Devolver a Central
                                </button>
                            )}
                        </div>
                    )}
                </div>

                <div className="flex gap-3">
                    {canDeriveUI && (
                        <button 
                            onClick={() => handleTransition(Status.DERIVACION)} 
                            className="bg-indigo-600 text-white px-8 py-4 rounded-[1.5rem] text-[11px] font-black uppercase tracking-[0.2em] shadow-2xl shadow-indigo-200 hover:bg-indigo-700 active:scale-95 transition-all flex items-center gap-3"
                        >
                            <UserCheck size={18}/> Derivar a Unidad
                        </button>
                    )}

                    {canExecuteUI && (
                        <button 
                            onClick={() => handleTransition(Status.EJECUCION)} 
                            className="bg-amber-500 text-white px-8 py-4 rounded-[1.5rem] text-[11px] font-black uppercase tracking-[0.2em] shadow-2xl shadow-amber-200 hover:bg-amber-600 active:scale-95 transition-all flex items-center gap-3"
                        >
                            <PlayCircle size={18}/> Iniciar Ejecución
                        </button>
                    )}

                    {canFinalizeUI && (
                        <button 
                            onClick={() => handleTransition(Status.FINALIZADO)} 
                            className="bg-emerald-600 text-white px-8 py-4 rounded-[1.5rem] text-[11px] font-black uppercase tracking-[0.2em] shadow-2xl shadow-emerald-200 hover:bg-emerald-700 active:scale-95 transition-all flex items-center gap-3"
                        >
                            <CheckCircle size={18} strokeWidth={3}/> Declarar Cumplimiento
                        </button>
                    )}

                    {isFinalized && activeRole === UserRole.SUPERADMIN && (
                        <button 
                            onClick={() => handleTransition(Status.RECIBIDO)} 
                            className="bg-slate-900 text-white px-8 py-4 rounded-[1.5rem] text-[11px] font-black uppercase tracking-[0.2em] shadow-2xl shadow-slate-200 hover:bg-slate-800 active:scale-95 transition-all flex items-center gap-3"
                        >
                            <ShieldAlert size={18}/> Reabrir para Auditoría
                        </button>
                    )}
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

