import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { User, RequestCard, Status, Priority, Area, UserRole, LogEntry } from '../types';
import { AREA_HEADS } from '../constants';
import { db } from '../services/storage';

interface SisreqContextType {
  currentUser: User | null;
  users: User[];
  isAuthenticated: boolean;
  isLoading: boolean;
  login: (user: User) => void;
  logout: () => void;
  setCurrentUser: (user: User) => void;
  updateUser: (updatedUser: User) => Promise<void>;
  addUser: (name: string, email: string, role: UserRole, password: string, area?: Area) => Promise<void>;

  requests: RequestCard[];
  selectedRequestId: string | null;
  setSelectedRequestId: (id: string | null) => void;
  addRequest: (title: string, detail: string, area: Area, priority: Priority, requester: string) => Promise<void>;
  updateStatus: (id: string, newStatus: Status) => Promise<void>;
  deleteRequest: (id: string) => Promise<void>;
  returnRequest: (id: string, reason: string) => Promise<void>;
  assignAnalyst: (id: string, analystName: string) => Promise<void>;
  addLog: (id: string, message: string) => Promise<void>;
  updateRequestDetails: (id: string, title: string, detail: string) => Promise<void>;

  viewMode: 'work' | 'superadmin';
  setViewMode: (mode: 'work' | 'superadmin') => void;

  activeRole: UserRole | null;
  setActiveRole: (role: UserRole) => void;

  globalFilterArea: Area | 'ALL';
  setGlobalFilterArea: (area: Area | 'ALL') => void;

  canUserTransition: (request: RequestCard, targetStatus: Status) => { allowed: boolean; reason?: string };
}

const SisreqContext = createContext<SisreqContextType | undefined>(undefined);

const generateId = (prefix: string) => `${prefix}-${Math.random().toString(36).substring(2, 8)}-${Date.now().toString(36)}`;

export const SisreqProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null); 
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [requests, setRequests] = useState<RequestCard[]>([]);
  const [selectedRequestId, setSelectedRequestId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'work' | 'superadmin'>('work');
  const [isLoading, setIsLoading] = useState(true);
  const [globalFilterArea, setGlobalFilterArea] = useState<Area | 'ALL'>('ALL');
  const [activeRole, setActiveRole] = useState<UserRole | null>(null);

  useEffect(() => {
    const initApp = async () => {
        try {
            await db.init();
            const [loadedRequests, loadedUsers] = await Promise.all([
                db.getRequests(),
                db.getUsers()
            ]);
            setRequests(loadedRequests.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()));
            setUsers(loadedUsers);
        } catch (error) {
            console.error("Critical Failure in SISREQ Core Engine:", error);
        } finally {
            setIsLoading(false);
        }
    };
    initApp();
  }, []);

  const login = (user: User) => {
    const foundUser = users.find(u => u.id === user.id) || user;
    setCurrentUser(foundUser);
    setIsAuthenticated(true);
    setViewMode('work');
    setGlobalFilterArea('ALL');
    setActiveRole(foundUser.role);
  };

  const logout = () => {
    setIsAuthenticated(false);
    setSelectedRequestId(null);
    setCurrentUser(null);
    setActiveRole(null);
  };

  const updateUser = useCallback(async (updatedUser: User) => {
    await db.saveUser(updatedUser);
    setUsers(prev => prev.map(u => u.id === updatedUser.id ? updatedUser : u));
    if (currentUser && currentUser.id === updatedUser.id) {
        setCurrentUser(updatedUser);
    }
  }, [currentUser]);

  const addUser = useCallback(async (name: string, email: string, role: UserRole, password: string, area?: Area) => {
    const newUser: User = {
        id: generateId('u'),
        name,
        email,
        role,
        area,
        password,
        status: 'ACTIVE',
        joinedAt: new Date().toISOString()
    };
    await db.saveUser(newUser);
    setUsers(prev => [...prev, newUser]);
  }, []);

  const canUserTransition = useCallback((request: RequestCard, targetStatus: Status): { allowed: boolean; reason?: string } => {
    if (!currentUser || !activeRole) return { allowed: false, reason: 'Sesión no identificada.' };
    if (request.status === targetStatus) return { allowed: true };

    // Regla de Oro: SuperAdmin ignora restricciones de flujo para correcciones de auditoría
    if (activeRole === UserRole.SUPERADMIN) return { allowed: true };

    // Protección de integridad para tickets finalizados
    if (request.status === Status.FINALIZADO && targetStatus !== Status.FINALIZADO) {
        return { allowed: false, reason: 'Solo Auditoría (SuperAdmin) puede revertir estados finalizados.' };
    }

    switch (activeRole) {
        case UserRole.ADMIN:
            // El Admin Central solo puede mover de Recibido a Derivación. No puede ejecutar.
            if (request.status === Status.RECIBIDO && targetStatus === Status.DERIVACION) return { allowed: true };
            return { allowed: false, reason: 'Como Administrador Central, su labor es la recepción y derivación inicial únicamente.' };

        case UserRole.HEAD:
            // El Jefe de Área solo puede mover sus propios tickets técnicos
            if (request.area !== currentUser.area) return { allowed: false, reason: 'Acceso denegado: Ticket fuera de su jurisdicción departamental.' };

            // Derivación -> Ejecución (Requiere Analista)
            if (request.status === Status.DERIVACION && targetStatus === Status.EJECUCION) {
                if (!request.assignedAnalyst) return { allowed: false, reason: 'Falta Asignación: Debe nombrar un analista responsable antes de iniciar ejecución.' };
                return { allowed: true };
            }
            // Ejecución -> Finalizado
            if (request.status === Status.EJECUCION && targetStatus === Status.FINALIZADO) return { allowed: true };

            return { allowed: false, reason: 'Transición no permitida para el rol de Jefatura en este estado.' };

        case UserRole.ANALYST:
            if (request.area !== currentUser.area) return { allowed: false, reason: 'Error de Seguridad: Intento de acceso a ticket de otra área técnica.' };
            // Los analistas solo pueden marcar como Finalizado lo que ya están Ejecutando
            if (request.status === Status.EJECUCION && targetStatus === Status.FINALIZADO) return { allowed: true };
            return { allowed: false, reason: 'Los analistas solo pueden cerrar tickets que ya están en fase de ejecución activa.' };

        default:
            return { allowed: false, reason: 'Rol de usuario no facultado para cambios de estado.' };
    }
  }, [currentUser, activeRole]);

  const addRequest = useCallback(async (title: string, detail: string, area: Area, priority: Priority, requester: string) => {
    if (!currentUser || !activeRole) return;
    const newRequest: RequestCard = {
      id: generateId('req'),
      title,
      detail,
      area,
      status: Status.RECIBIDO,
      priority,
      requester,
      responsibleHead: AREA_HEADS[area],
      createdAt: new Date().toISOString(),
      logs: [{
        id: generateId('log'),
        timestamp: new Date().toISOString(),
        message: `APERTURA: Requerimiento iniciado formalmente`,
        actor: currentUser.name,
        role: activeRole
      }]
    };
    await db.saveRequest(newRequest);
    setRequests(prev => [newRequest, ...prev]);
  }, [currentUser, activeRole]);

  const updateStatus = useCallback(async (id: string, newStatus: Status) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const { allowed, reason } = canUserTransition(req, newStatus);
    if (!allowed) throw new Error(reason);

    const isFinished = newStatus === Status.FINALIZADO;
    const isCentral = newStatus === Status.RECIBIDO;

    const updatedReq: RequestCard = {
        ...req,
        status: newStatus,
        finishedAt: isFinished ? new Date().toISOString() : (req.status === Status.FINALIZADO ? undefined : req.finishedAt),
        isReturned: isCentral ? true : (newStatus === Status.DERIVACION ? false : req.isReturned),
        assignedAnalyst: isCentral ? undefined : req.assignedAnalyst,
        lastUpdated: new Date().toISOString(),
        logs: [
          ...req.logs,
          {
            id: generateId('log'),
            timestamp: new Date().toISOString(),
            message: `TRANSICIÓN: Cambio de fase operativa a [${newStatus}]`,
            actor: currentUser.name,
            role: activeRole
          }
        ]
    };

    await db.saveRequest(updatedReq);
    setRequests(prev => prev.map(r => r.id === id ? updatedReq : r));
  }, [currentUser, requests, activeRole, canUserTransition]);

  const returnRequest = useCallback(async (id: string, reason: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    if (activeRole !== UserRole.HEAD && activeRole !== UserRole.SUPERADMIN && activeRole !== UserRole.ADMIN) {
        throw new Error("Privilegios insuficientes para devolver requerimientos a la central.");
    }

    const updatedReq: RequestCard = {
        ...req,
        status: Status.RECIBIDO,
        isReturned: true,
        assignedAnalyst: undefined, 
        lastUpdated: new Date().toISOString(),
        logs: [
          ...req.logs,
          {
            id: generateId('log'),
            timestamp: new Date().toISOString(),
            message: `RETORNO A CENTRAL: ${reason}`,
            actor: currentUser.name,
            role: activeRole
          }
        ]
    };
    await db.saveRequest(updatedReq);
    setRequests(prev => prev.map(r => r.id === id ? updatedReq : r));
  }, [currentUser, requests, activeRole]);

  const assignAnalyst = useCallback(async (id: string, analystName: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const updatedReq: RequestCard = {
        ...req,
        assignedAnalyst: analystName,
        lastUpdated: new Date().toISOString(),
        logs: [
          ...req.logs,
          {
            id: generateId('log'),
            timestamp: new Date().toISOString(),
            message: `ASIGNACIÓN TÉCNICA: ${analystName} nombrado responsable`,
            actor: currentUser.name,
            role: activeRole
          }
        ]
    };
    await db.saveRequest(updatedReq);
    setRequests(prev => prev.map(r => r.id === id ? updatedReq : r));
  }, [currentUser, requests, activeRole]);

  const deleteRequest = useCallback(async (id: string) => {
    if (activeRole !== UserRole.SUPERADMIN) return;
    await db.deleteRequest(id);
    setRequests(prev => prev.filter(r => r.id !== id));
  }, [activeRole]);

  const addLog = useCallback(async (id: string, message: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;
    const updatedReq: RequestCard = {
        ...req,
        lastUpdated: new Date().toISOString(),
        logs: [...req.logs, { 
            id: generateId('log'), 
            timestamp: new Date().toISOString(), 
            message, 
            actor: currentUser.name, 
            role: activeRole 
        }]
    };
    await db.saveRequest(updatedReq);
    setRequests(prev => prev.map(r => r.id === id ? updatedReq : r));
  }, [currentUser, requests, activeRole]);

  const updateRequestDetails = useCallback(async (id: string, title: string, detail: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;
    const updatedReq: RequestCard = { 
        ...req, 
        title, 
        detail,
        lastUpdated: new Date().toISOString(),
        logs: [...req.logs, { 
            id: generateId('log'), 
            timestamp: new Date().toISOString(), 
            message: 'EDICIÓN: Metadatos del ticket actualizados', 
            actor: currentUser.name, 
            role: activeRole 
        }]
    };
    await db.saveRequest(updatedReq);
    setRequests(prev => prev.map(r => r.id === id ? updatedReq : r));
  }, [requests, currentUser, activeRole]);

  return (
    <SisreqContext.Provider value={{
      currentUser,
      users,
      isAuthenticated,
      isLoading,
      login,
      logout,
      setCurrentUser,
      updateUser,
      addUser,
      requests,
      selectedRequestId,
      setSelectedRequestId,
      addRequest,
      updateStatus,
      deleteRequest,
      returnRequest,
      assignAnalyst,
      addLog,
      updateRequestDetails,
      viewMode,
      setViewMode,
      activeRole,
      setActiveRole,
      globalFilterArea,
      setGlobalFilterArea,
      canUserTransition
    }}>
      {children}
    </SisreqContext.Provider>
  );
};

export const useSisreq = () => {
  const context = useContext(SisreqContext);
  if (context === undefined) throw new Error('useSisreq must be used within a SisreqProvider');
  return context;
};

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { User, RequestCard, Status, Priority, Area, UserRole, LogEntry } from '../types';
import { AREA_HEADS } from '../constants';
import { db } from '../services/storage';

interface SisreqContextType {
  currentUser: User | null;
  users: User[];
  isAuthenticated: boolean;
  isLoading: boolean;
  login: (user: User) => void;
  logout: () => void;
  setCurrentUser: (user: User) => void;
  updateUser: (updatedUser: User) => Promise<void>;
  addUser: (name: string, email: string, role: UserRole, password: string, area?: Area) => Promise<void>;

  requests: RequestCard[];
  selectedRequestId: string | null;
  setSelectedRequestId: (id: string | null) => void;
  addRequest: (title: string, detail: string, area: Area, priority: Priority, requester: string) => Promise<void>;
  updateStatus: (id: string, newStatus: Status) => Promise<void>;
  deleteRequest: (id: string) => Promise<void>;
  returnRequest: (id: string, reason: string) => Promise<void>;
  assignAnalyst: (id: string, analystName: string) => Promise<void>;
  addLog: (id: string, message: string) => Promise<void>;
  updateRequestDetails: (id: string, title: string, detail: string) => Promise<void>;

  viewMode: 'work' | 'superadmin';
  setViewMode: (mode: 'work' | 'superadmin') => void;

  activeRole: UserRole | null;
  setActiveRole: (role: UserRole) => void;

  globalFilterArea: Area | 'ALL';
  setGlobalFilterArea: (area: Area | 'ALL') => void;

  canUserTransition: (request: RequestCard, targetStatus: Status) => { allowed: boolean; reason?: string };
}

const SisreqContext = createContext<SisreqContextType | undefined>(undefined);

const generateId = (prefix: string) => `${prefix}-${Math.random().toString(36).substring(2, 8)}-${Date.now().toString(36)}`;

export const SisreqProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null); 
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [requests, setRequests] = useState<RequestCard[]>([]);
  const [selectedRequestId, setSelectedRequestId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'work' | 'superadmin'>('work');
  const [isLoading, setIsLoading] = useState(true);
  const [globalFilterArea, setGlobalFilterArea] = useState<Area | 'ALL'>('ALL');
  const [activeRole, setActiveRole] = useState<UserRole | null>(null);

  useEffect(() => {
    const initApp = async () => {
        try {
            await db.init();
            const [loadedRequests, loadedUsers] = await Promise.all([
                db.getRequests(),
                db.getUsers()
            ]);
            setRequests(loadedRequests.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()));
            setUsers(loadedUsers);
        } catch (error) {
            console.error("Critical Failure in SISREQ Core Engine:", error);
        } finally {
            setIsLoading(false);
        }
    };
    initApp();
  }, []);

  const login = (user: User) => {
    const foundUser = users.find(u => u.id === user.id) || user;
    setCurrentUser(foundUser);
    setIsAuthenticated(true);
    setViewMode('work');
    setGlobalFilterArea('ALL');
    setActiveRole(foundUser.role);
  };

  const logout = () => {
    setIsAuthenticated(false);
    setSelectedRequestId(null);
    setCurrentUser(null);
    setActiveRole(null);
  };

  const updateUser = useCallback(async (updatedUser: User) => {
    await db.saveUser(updatedUser);
    setUsers(prev => prev.map(u => u.id === updatedUser.id ? updatedUser : u));
    if (currentUser && currentUser.id === updatedUser.id) {
        setCurrentUser(updatedUser);
    }
  }, [currentUser]);

  const addUser = useCallback(async (name: string, email: string, role: UserRole, password: string, area?: Area) => {
    const newUser: User = {
        id: generateId('u'),
        name,
        email,
        role,
        area,
        password,
        status: 'ACTIVE',
        joinedAt: new Date().toISOString()
    };
    await db.saveUser(newUser);
    setUsers(prev => [...prev, newUser]);
  }, []);

  const canUserTransition = useCallback((request: RequestCard, targetStatus: Status): { allowed: boolean; reason?: string } => {
    if (!currentUser || !activeRole) return { allowed: false, reason: 'Sesión no identificada.' };
    if (request.status === targetStatus) return { allowed: true };

    // SuperAdmin Bypass: Regla de Auditoría Superior
    if (activeRole === UserRole.SUPERADMIN) return { allowed: true };

    // Protección de integridad para tickets finalizados
    if (request.status === Status.FINALIZADO && targetStatus !== Status.FINALIZADO) {
        return { allowed: false, reason: 'Solo Auditoría (SuperAdmin) puede reabrir requerimientos finalizados.' };
    }

    switch (activeRole) {
        case UserRole.ADMIN:
            // Admin Central solo deriva de Recibido a Derivación
            if (request.status === Status.RECIBIDO && targetStatus === Status.DERIVACION) return { allowed: true };
            return { allowed: false, reason: 'Como Administrador Central, su labor es la recepción y derivación inicial únicamente.' };

        case UserRole.HEAD:
            // Jurisdicción Técnica
            if (request.area !== currentUser.area) return { allowed: false, reason: 'Acceso denegado: Ticket fuera de su jurisdicción departamental.' };

            // Derivación -> Ejecución (Requiere Analista)
            if (request.status === Status.DERIVACION && targetStatus === Status.EJECUCION) {
                if (!request.assignedAnalyst) return { allowed: false, reason: 'Falta Asignación: Debe nombrar un analista responsable antes de iniciar ejecución.' };
                return { allowed: true };
            }
            // Ejecución -> Finalizado
            if (request.status === Status.EJECUCION && targetStatus === Status.FINALIZADO) return { allowed: true };

            return { allowed: false, reason: 'La jefatura no tiene facultades para esta transición en el estado actual.' };

        case UserRole.ANALYST:
            if (request.area !== currentUser.area) return { allowed: false, reason: 'Seguridad: No puede procesar tickets de otras unidades técnicas.' };
            // Los analistas solo cierran lo que ya ejecutan
            if (request.status === Status.EJECUCION && targetStatus === Status.FINALIZADO) return { allowed: true };
            return { allowed: false, reason: 'Los analistas solo pueden finalizar tickets asignados en fase de ejecución.' };

        default:
            return { allowed: false, reason: 'Rol de usuario no facultado para cambios de estado operativo.' };
    }
  }, [currentUser, activeRole]);

  const addRequest = useCallback(async (title: string, detail: string, area: Area, priority: Priority, requester: string) => {
    if (!currentUser || !activeRole) return;
    const newRequest: RequestCard = {
      id: generateId('req'),
      title,
      detail,
      area,
      status: Status.RECIBIDO,
      priority,
      requester,
      responsibleHead: AREA_HEADS[area],
      createdAt: new Date().toISOString(),
      logs: [{
        id: generateId('log'),
        timestamp: new Date().toISOString(),
        message: `APERTURA: Requerimiento iniciado formalmente`,
        actor: currentUser.name,
        role: activeRole
      }]
    };
    await db.saveRequest(newRequest);
    setRequests(prev => [newRequest, ...prev]);
  }, [currentUser, activeRole]);

  const updateStatus = useCallback(async (id: string, newStatus: Status) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const { allowed, reason } = canUserTransition(req, newStatus);
    if (!allowed) throw new Error(reason);

    const isFinished = newStatus === Status.FINALIZADO;
    const isReturningToCentral = newStatus === Status.RECIBIDO;

    const updatedReq: RequestCard = {
        ...req,
        status: newStatus,
        finishedAt: isFinished ? new Date().toISOString() : (req.status === Status.FINALIZADO ? undefined : req.finishedAt),
        isReturned: isReturningToCentral ? true : (newStatus === Status.DERIVACION ? false : req.isReturned),
        assignedAnalyst: isReturningToCentral ? undefined : req.assignedAnalyst,
        lastUpdated: new Date().toISOString(),
        logs: [
          ...req.logs,
          {
            id: generateId('log'),
            timestamp: new Date().toISOString(),
            message: `TRANSICIÓN: Fase actualizada a [${newStatus}]`,
            actor: currentUser.name,
            role: activeRole
          }
        ]
    };

    await db.saveRequest(updatedReq);
    setRequests(prev => prev.map(r => r.id === id ? updatedReq : r));
  }, [currentUser, requests, activeRole, canUserTransition]);

  const returnRequest = useCallback(async (id: string, reason: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const updatedReq: RequestCard = {
        ...req,
        status: Status.RECIBIDO,
        isReturned: true,
        assignedAnalyst: undefined, 
        lastUpdated: new Date().toISOString(),
        logs: [
          ...req.logs,
          {
            id: generateId('log'),
            timestamp: new Date().toISOString(),
            message: `DEVOLUCIÓN A CENTRAL: ${reason}`,
            actor: currentUser.name,
            role: activeRole
          }
        ]
    };
    await db.saveRequest(updatedReq);
    setRequests(prev => prev.map(r => r.id === id ? updatedReq : r));
  }, [currentUser, requests, activeRole]);

  const assignAnalyst = useCallback(async (id: string, analystName: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const updatedReq: RequestCard = {
        ...req,
        assignedAnalyst: analystName,
        lastUpdated: new Date().toISOString(),
        logs: [
          ...req.logs,
          {
            id: generateId('log'),
            timestamp: new Date().toISOString(),
            message: `ASIGNACIÓN TÉCNICA: ${analystName} nombrado responsable de ejecución`,
            actor: currentUser.name,
            role: activeRole
          }
        ]
    };
    await db.saveRequest(updatedReq);
    setRequests(prev => prev.map(r => r.id === id ? updatedReq : r));
  }, [currentUser, requests, activeRole]);

  const deleteRequest = useCallback(async (id: string) => {
    if (activeRole !== UserRole.SUPERADMIN) return;
    await db.deleteRequest(id);
    setRequests(prev => prev.filter(r => r.id !== id));
  }, [activeRole]);

  const addLog = useCallback(async (id: string, message: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;
    const updatedReq: RequestCard = {
        ...req,
        lastUpdated: new Date().toISOString(),
        logs: [...req.logs, { 
            id: generateId('log'), 
            timestamp: new Date().toISOString(), 
            message, 
            actor: currentUser.name, 
            role: activeRole 
        }]
    };
    await db.saveRequest(updatedReq);
    setRequests(prev => prev.map(r => r.id === id ? updatedReq : r));
  }, [currentUser, requests, activeRole]);

  const updateRequestDetails = useCallback(async (id: string, title: string, detail: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;
    const updatedReq: RequestCard = { 
        ...req, 
        title, 
        detail,
        lastUpdated: new Date().toISOString(),
        logs: [...req.logs, { 
            id: generateId('log'), 
            timestamp: new Date().toISOString(), 
            message: 'EDICIÓN: Metadatos del requerimiento modificados', 
            actor: currentUser.name, 
            role: activeRole 
        }]
    };
    await db.saveRequest(updatedReq);
    setRequests(prev => prev.map(r => r.id === id ? updatedReq : r));
  }, [requests, currentUser, activeRole]);

  return (
    <SisreqContext.Provider value={{
      currentUser,
      users,
      isAuthenticated,
      isLoading,
      login,
      logout,
      setCurrentUser,
      updateUser,
      addUser,
      requests,
      selectedRequestId,
      setSelectedRequestId,
      addRequest,
      updateStatus,
      deleteRequest,
      returnRequest,
      assignAnalyst,
      addLog,
      updateRequestDetails,
      viewMode,
      setViewMode,
      activeRole,
      setActiveRole,
      globalFilterArea,
      setGlobalFilterArea,
      canUserTransition
    }}>
      {children}
    </SisreqContext.Provider>
  );
};

