  const [editDetail, setEditDetail] = useState('');
  const [newComment, setNewComment] = useState('');
  const [actionError, setActionError] = useState<string | null>(null);

  const data = requests.find(r => r.id === selectedRequestId);

  useEffect(() => {
     if (data) {
        setEditTitle(data.title);
        setEditDetail(data.detail);
        setIsEditing(false);
        setShowReturnInput(false);
        setShowAnalystSelect(false);
        setNewComment('');
        setActionError(null);
     }
  }, [selectedRequestId, data]);

  if (!selectedRequestId || !data || !currentUser) return null;

  const handleClose = () => setSelectedRequestId(null);
  const isFinalized = data.status === Status.FINALIZADO;

  const handleTransition = async (targetStatus: Status) => {
    setActionError(null);
    try {
        await updateStatus(data.id, targetStatus);
    } catch (e: any) {
        setActionError(e.message);
    }
  };

  const handleReturnSubmit = async () => {
    if (returnReason.trim()) {
      try {
        await returnRequest(data.id, returnReason);
        setShowReturnInput(false);
        setReturnReason('');
      } catch (e: any) {
        setActionError(e.message);
      }
    }
  };

  const handleAssignAnalyst = (analystName: string) => {
    assignAnalyst(data.id, analystName);
    setShowAnalystSelect(false);
  };

  const handleSaveChanges = async () => {
    if (editTitle.trim() && editDetail.trim()) {
        await updateRequestDetails(data.id, editTitle, editDetail);
        setIsEditing(false);
    }
  };

  const handleAddComment = async () => {
    if (newComment.trim()) {
        await addLog(data.id, `MENSAJE INTERNO: ${newComment}`);
        setNewComment('');
    }
  };

  const availableAssignees = users.filter(u => 
    (u.role === UserRole.ANALYST || u.role === UserRole.HEAD) && 
    u.area === data.area &&
    (u.status === 'ACTIVE' || !u.status)
  );

  const canDeriveUI = canUserTransition(data, Status.DERIVACION).allowed;
  const canExecuteUI = canUserTransition(data, Status.EJECUCION).allowed;
  const canFinalizeUI = canUserTransition(data, Status.FINALIZADO).allowed;
  const canEditUI = activeRole === UserRole.ADMIN || activeRole === UserRole.SUPERADMIN;

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-900/80 backdrop-blur-md transition-opacity" onClick={handleClose}></div>

      <div className={`relative bg-white rounded-[2.5rem] shadow-2xl w-full max-w-2xl max-h-[92vh] flex flex-col overflow-hidden animate-in fade-in zoom-in-95 duration-300 border border-slate-200 border-t-[12px] ${isFinalized ? 'border-emerald-500' : 'border-indigo-600'}`}>

        {/* Header Section */}
        <div className="bg-slate-50 border-b border-slate-100 px-8 py-6 flex justify-between items-center shrink-0">
          <div className="flex items-center gap-5 min-w-0">
             <div className={`p-3.5 rounded-2xl text-white shrink-0 shadow-lg ${isFinalized ? 'bg-emerald-600' : 'bg-slate-800'}`}>
                {isFinalized ? <CheckCircle2 size={24} strokeWidth={2.5}/> : <ClipboardList size={24} strokeWidth={2.5} />}
             </div>
             <div className="min-w-0">
                <div className="flex items-center gap-2 mb-1.5">
                    <span className={`px-3 py-0.5 rounded-lg text-[10px] font-black uppercase tracking-[0.15em] shadow-sm ring-1 ring-black/5 ${STATUS_BADGE_COLORS[data.status]}`}>
                        {data.status}
                    </span>
                    <span className="text-[10px] text-slate-400 font-mono font-black bg-white px-2 py-0.5 rounded border border-slate-100 flex items-center gap-1">
                        <Hash size={10} className="opacity-40"/>{data.id.split('-')[1].toUpperCase()}
                    </span>
                </div>
                {isEditing ? (
                    <input 
                        value={editTitle}
                        onChange={e => setEditTitle(e.target.value)}
                        className="text-xl font-black text-slate-900 w-full bg-white border-b-2 border-indigo-500 outline-none uppercase"
                    />
                ) : (
                    <h2 className="text-xl font-black text-slate-900 truncate uppercase tracking-tight">{data.title}</h2>
                )}
             </div>
          </div>
          <button onClick={handleClose} className="p-2.5 text-slate-300 hover:text-slate-900 hover:bg-white rounded-full transition-all border border-transparent hover:border-slate-100">
            <X size={24} />
          </button>
        </div>

        {/* Content Section */}
        <div className="flex-1 overflow-y-auto p-8 space-y-10 bg-white custom-scrollbar">

            {/* Descriptive Area */}
            <div className="space-y-3">
                <div className="flex items-center justify-between">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
                        <PenTool size={14} className="text-indigo-500"/> Memoria Descriptiva
                    </label>
                    {canEditUI && !isEditing && (
                        <button onClick={() => setIsEditing(true)} className="text-[10px] font-black text-indigo-600 uppercase hover:underline">Editar Expediente</button>
                    )}
                </div>
                {isEditing ? (
                    <textarea 
                        value={editDetail}
                        onChange={e => setEditDetail(e.target.value)}
                        className="w-full bg-slate-50 border-2 border-indigo-100 p-6 rounded-[2rem] text-sm text-slate-700 leading-relaxed outline-none min-h-[150px]"
                    />
                ) : (
                    <div className="bg-slate-50/50 p-6 rounded-[2rem] border border-slate-100 italic text-slate-600 text-sm leading-relaxed shadow-inner">
                        "{data.detail}"
                    </div>
                )}
                {isEditing && (
                    <div className="flex justify-end gap-3 pt-2">
                        <button onClick={() => setIsEditing(false)} className="px-4 py-2 text-[10px] font-bold text-slate-400 uppercase">Descartar</button>
                        <button onClick={handleSaveChanges} className="bg-indigo-600 text-white px-6 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg shadow-indigo-100 flex items-center gap-2">
                            <Save size={14}/> Guardar Cambios
                        </button>
                    </div>
                )}
            </div>

            {/* Context Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="p-5 bg-white border border-slate-100 rounded-3xl shadow-sm group hover:border-indigo-100 transition-colors">
                    <p className="text-[9px] font-black text-slate-400 uppercase mb-2 flex items-center gap-2">
                        <User size={12}/> Unidad Solicitante
                    </p>
                    <p className="text-[13px] font-black text-slate-800 truncate uppercase tracking-tight">{data.requester}</p>
                </div>
                <div className="p-5 bg-white border border-slate-100 rounded-3xl shadow-sm group hover:border-indigo-100 transition-colors">
                    <p className="text-[9px] font-black text-slate-400 uppercase mb-2 flex items-center gap-2">
                        <Building size={12}/> Departamento Destino
                    </p>
                    <p className="text-[13px] font-black text-slate-800 uppercase tracking-tight">{data.area}</p>
                </div>
            </div>

            {/* Technical Assignment */}
            <div className="p-6 bg-indigo-50/50 border border-indigo-100 rounded-[2.5rem] flex flex-col md:flex-row items-center gap-6">
                <div className={`w-14 h-14 rounded-2xl flex items-center justify-center text-white font-black text-lg shadow-lg ${data.assignedAnalyst ? 'bg-indigo-600' : 'bg-slate-300'}`}>
                    {data.assignedAnalyst ? data.assignedAnalyst.substring(0,2).toUpperCase() : '?'}
                </div>
                <div className="flex-1 text-center md:text-left">
                    <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">Responsable de Ejecución</p>
                    <p className={`text-base font-black uppercase tracking-tight ${data.assignedAnalyst ? 'text-indigo-900' : 'text-slate-400 italic'}`}>
                        {data.assignedAnalyst || 'Personal técnico no asignado'}
                    </p>
                </div>
                {activeRole === UserRole.HEAD && data.status === Status.DERIVACION && (
                    <div className="relative">
                        <button 
                            onClick={() => setShowAnalystSelect(!showAnalystSelect)}
                            className="bg-white border-2 border-indigo-200 text-indigo-600 px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-indigo-600 hover:text-white transition-all shadow-sm"
                        >
                            {data.assignedAnalyst ? 'Reasignar' : 'Nombrar Responsable'}
                        </button>
                        {showAnalystSelect && (
                            <div className="absolute bottom-full right-0 mb-3 w-64 bg-white border border-slate-200 shadow-2xl rounded-2xl p-2 z-[70] animate-in slide-in-from-bottom-2">
                                <div className="p-3 border-b border-slate-50 text-[9px] font-black text-slate-400 uppercase tracking-widest">Personal de {data.area}</div>
                                {availableAssignees.map(u => (
                                    <button 
                                        key={u.id} 
                                        onClick={() => handleAssignAnalyst(u.name)} 
                                        className="w-full text-left px-4 py-3 hover:bg-indigo-50 rounded-xl text-[11px] font-black text-slate-700 uppercase transition-colors"
                                    >
                                        {u.name}
                                    </button>
                                ))}
                                {availableAssignees.length === 0 && <div className="p-4 text-[10px] italic text-slate-400">No hay analistas activos en esta unidad operativa</div>}
                            </div>
                        )}
                    </div>
                )}
            </div>

            {/* Audit Log / Comments */}
            <div className="space-y-6 pt-6 border-t border-slate-100">
                <div className="flex items-center justify-between">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
                        <History size={14}/> Historial de Auditoría Inmutable
                    </label>
                    <span className="text-[9px] font-black text-slate-300 uppercase tracking-widest bg-slate-50 px-2 py-1 rounded-lg">Traceability Protocol</span>
                </div>

                <div className="space-y-4">
                    <div className="flex gap-4">
                         <div className="w-10 h-10 rounded-xl bg-slate-100 border border-slate-200 flex items-center justify-center text-slate-400 shrink-0">
                            <MessageSquare size={18}/>
                         </div>
                         <div className="flex-1 flex gap-2">
                            <input 
                                value={newComment}
                                onChange={e => setNewComment(e.target.value)}
                                placeholder="Añadir nota técnica o instrucción..."
                                className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-4 text-xs font-medium focus:outline-none focus:ring-4 focus:ring-indigo-500/5 focus:border-indigo-400"
                            />
                            <button 
                                onClick={handleAddComment}
                                disabled={!newComment.trim()}
                                className="bg-slate-900 text-white p-2.5 rounded-xl disabled:opacity-30 hover:bg-slate-800 transition-colors"
                            >
                                <Send size={16}/>
                            </button>
                         </div>
                    </div>

                    <div className="space-y-4 pt-2">
                        {[...data.logs].reverse().map((log) => (
                            <div key={log.id} className="flex gap-4 group">
                                <div className="shrink-0 w-2.5 h-2.5 rounded-full bg-slate-200 mt-4 relative z-10 border-2 border-white group-first:bg-indigo-500 group-first:w-3 group-first:h-3"></div>
                                <div className="flex-1 bg-slate-50/50 p-4 rounded-2xl border border-slate-100 group-first:bg-white group-first:shadow-sm group-first:border-indigo-100">
                                    <div className="flex justify-between items-center mb-1">
                                        <div className="flex items-center gap-2">
                                            <span className="text-[11px] font-black text-slate-800 uppercase tracking-tight">{log.actor}</span>
                                            <span className="px-1.5 py-0.5 bg-slate-100 rounded text-[8px] font-black text-slate-400 uppercase tracking-widest">{log.role}</span>
                                        </div>
                                        <span className="text-[9px] text-slate-400 font-mono font-bold">
                                            {new Date(log.timestamp).toLocaleDateString()} {new Date(log.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                                        </span>
                                    </div>
                                    <p className="text-[11px] text-slate-600 font-bold uppercase tracking-tight leading-relaxed">{log.message}</p>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        </div>

        {/* Footer Actions */}
        <div className="bg-white border-t border-slate-100 p-8 flex flex-col gap-4 shrink-0">
            {actionError && (
                <div className="bg-red-50 border border-red-100 p-4 rounded-2xl flex items-center gap-4 text-red-600 text-[11px] font-black uppercase tracking-widest animate-in slide-in-from-top-2 shadow-sm">
                    <ShieldAlert size={18}/> {actionError}
                </div>
            )}

            <div className="flex justify-between items-center gap-4">
                <div className="flex items-center gap-2">
                    {activeRole === UserRole.SUPERADMIN && (
                        <button 
                            onClick={() => { if(confirm('¿ELIMINAR REQUERIMIENTO PERMANENTEMENTE?')) { deleteRequest(data.id); handleClose(); }}} 
                            className="p-3 text-red-400 hover:text-red-600 hover:bg-red-50 rounded-2xl transition-all border border-transparent hover:border-red-100"
                            title="Eliminar Requerimiento"
                        >
                            <Trash2 size={20}/>
                        </button>
                    )}

                    {(activeRole === UserRole.HEAD || activeRole === UserRole.SUPERADMIN || activeRole === UserRole.ADMIN) && data.status !== Status.RECIBIDO && data.status !== Status.FINALIZADO && (
                        <div className="flex items-center gap-2">
                            {showReturnInput ? (
                                <div className="flex items-center gap-2 bg-red-50 p-1.5 rounded-2xl border border-red-100 animate-in slide-in-from-left-4">
                                    <input 
                                        autoFocus
                                        value={returnReason}
                                        onChange={e => setReturnReason(e.target.value)}
                                        placeholder="Motivo de devolución..."
                                        className="bg-white border border-red-200 px-4 py-2 rounded-xl text-[10px] font-bold text-red-900 outline-none w-48"
                                    />
                                    <button onClick={handleReturnSubmit} className="bg-red-600 text-white px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest">Confirmar</button>
                                    <button onClick={() => setShowReturnInput(false)} className="p-2 text-red-400"><X size={16}/></button>
                                </div>
                            ) : (
                                <button 
                                    onClick={() => setShowReturnInput(true)} 
                                    className="px-6 py-3 rounded-2xl text-[10px] font-black text-red-600 border-2 border-red-100 hover:bg-red-50 transition-all uppercase tracking-widest flex items-center gap-2"
                                >
                                    <RotateCcw size={14} strokeWidth={3}/> Devolver a Central
                                </button>
                            )}
                        </div>
                    )}
                </div>

                <div className="flex gap-3">
                    {canDeriveUI && (
                        <button 
                            onClick={() => handleTransition(Status.DERIVACION)} 
                            className="bg-indigo-600 text-white px-8 py-4 rounded-[1.5rem] text-[11px] font-black uppercase tracking-[0.2em] shadow-2xl shadow-indigo-200 hover:bg-indigo-700 active:scale-95 transition-all flex items-center gap-3"
                        >
                            <UserCheck size={18}/> Derivar a Unidad
                        </button>
                    )}

                    {canExecuteUI && (
                        <button 
                            onClick={() => handleTransition(Status.EJECUCION)} 
                            className="bg-amber-500 text-white px-8 py-4 rounded-[1.5rem] text-[11px] font-black uppercase tracking-[0.2em] shadow-2xl shadow-amber-200 hover:bg-amber-600 active:scale-95 transition-all flex items-center gap-3"
                        >
                            <PlayCircle size={18}/> Iniciar Ejecución
                        </button>
                    )}

                    {canFinalizeUI && (
                        <button 
                            onClick={() => handleTransition(Status.FINALIZADO)} 
                            className="bg-emerald-600 text-white px-8 py-4 rounded-[1.5rem] text-[11px] font-black uppercase tracking-[0.2em] shadow-2xl shadow-emerald-200 hover:bg-emerald-700 active:scale-95 transition-all flex items-center gap-3"
                        >
                            <CheckCircle size={18} strokeWidth={3}/> Declarar Cumplimiento
                        </button>
                    )}

                    {isFinalized && activeRole === UserRole.SUPERADMIN && (
                        <button 
                            onClick={() => handleTransition(Status.RECIBIDO)} 
                            className="bg-slate-900 text-white px-8 py-4 rounded-[1.5rem] text-[11px] font-black uppercase tracking-[0.2em] shadow-2xl shadow-slate-200 hover:bg-slate-800 active:scale-95 transition-all flex items-center gap-3"
                        >
                            <ShieldAlert size={18}/> Reabrir para Auditoría
                        </button>
                    )}
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

export enum UserRole {
  SUPERADMIN = 'SUPERADMIN', // Control Total: Auditoría y Configuración Global
  ADMIN = 'ADMIN',           // Gestión Central: Recepción y Derivación inicial
  HEAD = 'HEAD',            // Jefatura de Área: Gestión técnica y asignación
  ANALYST = 'ANALYST'       // Analista Técnico: Ejecución de tareas
}

export enum Area {
  CONTABILIDAD = 'Contabilidad',
  RRHH = 'RRHH',
  ACREDITACION = 'Acreditación',
  FINANZAS = 'Finanzas'
}

export enum Status {
  RECIBIDO = 'Recibido',      // En Bandeja Central (Esperando Derivación)
  DERIVACION = 'En Derivación', // En Bandeja de Jefatura (Esperando Analista)
  EJECUCION = 'En Ejecución',   // En proceso técnico por un Analista
  FINALIZADO = 'Finalizado'     // Requerimiento cumplido y cerrado
}

export enum Priority {
  HIGH = 'Alta',
  MEDIUM = 'Media',
  LOW = 'Baja'
}

export type UserStatus = 'ACTIVE' | 'INACTIVE';

export interface User {
  id: string;
  name: string;
  email: string;
  role: UserRole;
  area?: Area; // Obligatorio para HEAD y ANALYST
  password?: string;
  status?: UserStatus;
  joinedAt?: string;
}

export interface LogEntry {
  id: string;
  timestamp: string;
  message: string;
  actor: string;
  role: UserRole;
}

export interface RequestCard {
  id: string;
  title: string;
  detail: string;
  requester: string;
  area: Area;
  status: Status;
  priority: Priority;
  responsibleHead: string; 
  assignedAnalyst?: string; 
  logs: LogEntry[];
  createdAt: string;
  lastUpdated: string;
  finishedAt?: string;
  isReturned?: boolean; 
}

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { User, RequestCard, Status, Priority, Area, UserRole, LogEntry } from '../types';
import { AREA_HEADS } from '../constants';
import { db } from '../services/storage';

interface SisreqContextType {
  currentUser: User | null;
  users: User[];
  requests: RequestCard[];
  isAuthenticated: boolean;
  isLoading: boolean;
  activeRole: UserRole | null;
  globalFilterArea: Area | 'ALL';
  selectedRequestId: string | null;

  // Auth & User Actions
  login: (user: User) => void;
  logout: () => void;
  setActiveRole: (role: UserRole) => void;
  addUser: (name: string, email: string, role: UserRole, password: string, area?: Area) => Promise<void>;
  updateUser: (updatedUser: User) => Promise<void>;

  // Request Actions
  setSelectedRequestId: (id: string | null) => void;
  setGlobalFilterArea: (area: Area | 'ALL') => void;
  addRequest: (title: string, detail: string, area: Area, priority: Priority, requester: string) => Promise<void>;
  updateStatus: (id: string, newStatus: Status) => Promise<void>;
  returnRequest: (id: string, reason: string) => Promise<void>;
  assignAnalyst: (id: string, analystName: string) => Promise<void>;
  addLog: (id: string, message: string) => Promise<void>;
  updateRequestDetails: (id: string, title: string, detail: string) => Promise<void>;
  deleteRequest: (id: string) => Promise<void>;

  // Policy Engine
  canUserTransition: (request: RequestCard, targetStatus: Status) => { allowed: boolean; reason?: string };
  canUserSeeRequest: (request: RequestCard) => boolean;
}

const SisreqContext = createContext<SisreqContextType | undefined>(undefined);

const genId = (p: string) => `${p}-${Math.random().toString(36).substr(2, 9)}`;

export const SisreqProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [requests, setRequests] = useState<RequestCard[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeRole, setActiveRole] = useState<UserRole | null>(null);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [globalFilterArea, setGlobalFilterArea] = useState<Area | 'ALL'>('ALL');
  const [selectedRequestId, setSelectedRequestId] = useState<string | null>(null);

  useEffect(() => {
    const init = async () => {
      try {
        await db.init();
        const [u, r] = await Promise.all([db.getUsers(), db.getRequests()]);
        setUsers(u);
        setRequests(r.sort((a, b) => new Date(b.lastUpdated || b.createdAt).getTime() - new Date(a.lastUpdated || a.createdAt).getTime()));
      } catch (e) {
        console.error("Critical: Storage failed", e);
      } finally {
        setIsLoading(false);
      }
    };
    init();
  }, []);

  const login = (user: User) => {
    setCurrentUser(user);
    setActiveRole(user.role);
    setIsAuthenticated(true);
    setGlobalFilterArea(user.role === UserRole.ADMIN || user.role === UserRole.SUPERADMIN ? 'ALL' : (user.area as Area));
  };

  const logout = () => {
    setIsAuthenticated(false);
    setCurrentUser(null);
    setActiveRole(null);
    setSelectedRequestId(null);
  };

  // --- WORKFLOW POLICIES ---

  const canUserSeeRequest = useCallback((req: RequestCard): boolean => {
    if (!currentUser || !activeRole) return false;

    // SuperAdmin y Admin Central ven todo el ecosistema
    if (activeRole === UserRole.SUPERADMIN || activeRole === UserRole.ADMIN) return true;

    // Jefes y Analistas ven solo su Área, pero excluyendo lo que aún está en Bandeja Central
    const isSameArea = req.area === currentUser.area;
    const isOutFromCentral = req.status !== Status.RECIBIDO;

    return isSameArea && isOutFromCentral;
  }, [currentUser, activeRole]);

  const canUserTransition = useCallback((req: RequestCard, target: Status): { allowed: boolean; reason?: string } => {
    if (!currentUser || !activeRole) return { allowed: false, reason: 'No autenticado' };
    if (req.status === target) return { allowed: true };
    if (activeRole === UserRole.SUPERADMIN) return { allowed: true };

    // Regla de Inmutabilidad de Finalizados
    if (req.status === Status.FINALIZADO && activeRole !== UserRole.SUPERADMIN) {
        return { allowed: false, reason: 'Solo Auditoría Superior puede reabrir casos finalizados.' };
    }

    switch (activeRole) {
      case UserRole.ADMIN:
        if (req.status === Status.RECIBIDO && target === Status.DERIVACION) return { allowed: true };
        return { allowed: false, reason: 'Labor administrativa limitada a la derivación inicial.' };

      case UserRole.HEAD:
        if (req.area !== currentUser.area) return { allowed: false, reason: 'Fuera de jurisdicción' };
        if (req.status === Status.DERIVACION && target === Status.EJECUCION) {
            if (!req.assignedAnalyst) return { allowed: false, reason: 'Debe asignar un analista antes de iniciar ejecución.' };
            return { allowed: true };
        }
        if (req.status === Status.EJECUCION && target === Status.FINALIZADO) return { allowed: true };
        return { allowed: false, reason: 'Transición no permitida para Jefatura en este estado.' };

      case UserRole.ANALYST:
        if (req.area !== currentUser.area) return { allowed: false, reason: 'Fuera de jurisdicción' };
        if (req.status === Status.EJECUCION && target === Status.FINALIZADO) return { allowed: true };
        return { allowed: false, reason: 'Analistas solo pueden finalizar tickets en ejecución.' };

      default:
        return { allowed: false, reason: 'Rol sin permisos de transición.' };
    }
  }, [currentUser, activeRole]);

  // --- ACTIONS ---

  const addRequest = async (title: string, detail: string, area: Area, priority: Priority, requester: string) => {
    const now = new Date().toISOString();
    const newReq: RequestCard = {
      id: genId('REQ'),
      title, detail, area, priority, requester,
      status: Status.RECIBIDO,
      responsibleHead: AREA_HEADS[area],
      createdAt: now,
      lastUpdated: now,
      logs: [{
        id: genId('LOG'),
        timestamp: now,
        message: 'APERTURA: Registro formal de requerimiento',
        actor: currentUser?.name || 'Sistema',
        role: activeRole || UserRole.ADMIN
      }]
    };
    await db.saveRequest(newReq);
    setRequests(prev => [newReq, ...prev]);
  };

  const updateStatus = async (id: string, newStatus: Status) => {
    const req = requests.find(r => r.id === id);
    if (!req) return;

    const policy = canUserTransition(req, newStatus);
    if (!policy.allowed) throw new Error(policy.reason);

    const now = new Date().toISOString();
    const isReturning = newStatus === Status.RECIBIDO;

    const updated: RequestCard = {
      ...req,
      status: newStatus,
      lastUpdated: now,
      finishedAt: newStatus === Status.FINALIZADO ? now : req.finishedAt,
      assignedAnalyst: isReturning ? undefined : req.assignedAnalyst,
      isReturned: isReturning ? true : (newStatus === Status.DERIVACION ? false : req.isReturned),
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: `TRANSICIÓN: Estado actualizado a [${newStatus.toUpperCase()}]`,
        actor: currentUser!.name,
        role: activeRole!
      }]
    };
    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const returnRequest = async (id: string, reason: string) => {
    const req = requests.find(r => r.id === id);
    if (!req) return;
    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      status: Status.RECIBIDO,
      isReturned: true,
      assignedAnalyst: undefined,
      lastUpdated: now,
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: `DEVOLUCIÓN A CENTRAL: ${reason}`,
        actor: currentUser!.name,
        role: activeRole!
      }]
    };
    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const assignAnalyst = async (id: string, name: string) => {
    const req = requests.find(r => r.id === id);
    if (!req) return;
    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      assignedAnalyst: name,
      lastUpdated: now,
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: `ASIGNACIÓN: ${name} designado responsable técnico`,
        actor: currentUser!.name,
        role: activeRole!
      }]
    };
    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const addLog = async (id: string, msg: string) => {
    const req = requests.find(r => r.id === id);
    if (!req) return;
    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      lastUpdated: now,
      logs: [...req.logs, { id: genId('LOG'), timestamp: now, message: msg, actor: currentUser!.name, role: activeRole! }]
    };
    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const updateRequestDetails = async (id: string, title: string, detail: string) => {
    const req = requests.find(r => r.id === id);
    if (!req) return;
    const now = new Date().toISOString();
    const updated: RequestCard = { ...req, title, detail, lastUpdated: now };
    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const deleteRequest = async (id: string) => {
    await db.deleteRequest(id);
    setRequests(prev => prev.filter(r => r.id !== id));
  };

  const addUser = async (name: string, email: string, role: UserRole, pass: string, area?: Area) => {
    const newUser: User = { id: genId('U'), name, email, role, area, password: pass, status: 'ACTIVE', joinedAt: new Date().toISOString() };
    await db.saveUser(newUser);
    setUsers(prev => [...prev, newUser]);
  };

  const updateUser = async (u: User) => {
    await db.saveUser(u);
    setUsers(prev => prev.map(old => old.id === u.id ? u : old));
    if (currentUser?.id === u.id) setCurrentUser(u);
  };

  return (
    <SisreqContext.Provider value={{
      currentUser, users, requests, isAuthenticated, isLoading, activeRole, globalFilterArea, selectedRequestId,
      login, logout, setActiveRole, addUser, updateUser,
      setSelectedRequestId, setGlobalFilterArea, addRequest, updateStatus, returnRequest, assignAnalyst, addLog, updateRequestDetails, deleteRequest,
      canUserTransition, canUserSeeRequest
    }}>
      {children}
    </SisreqContext.Provider>
  );
};

export const useSisreq = () => {
  const ctx = useContext(SisreqContext);
  if (!ctx) throw new Error("Context failed");
  return ctx;
};

import React, { useState, useMemo } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { RequestCard } from './RequestCard';
import { Status, Area } from '../types';
import { LayoutGrid, List, Search, Inbox, GitPullRequest, PlayCircle, CheckCircle2, ChevronDown, Filter, LayoutDashboard } from 'lucide-react';

export const Board: React.FC = () => {
  const { requests, currentUser, updateStatus, globalFilterArea, setGlobalFilterArea, activeRole, canUserSeeRequest } = useSisreq();
  const [dragOverColumn, setDragOverColumn] = useState<Status | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  const filteredRequests = useMemo(() => {
    return requests.filter(req => {
      if (!canUserSeeRequest(req)) return false;

      const term = searchTerm.toLowerCase();
      const matchesSearch = searchTerm === '' || 
          req.title.toLowerCase().includes(term) ||
          req.id.toLowerCase().includes(term) ||
          req.requester.toLowerCase().includes(term) ||
          (req.assignedAnalyst && req.assignedAnalyst.toLowerCase().includes(term));

      const matchesArea = globalFilterArea === 'ALL' || req.area === globalFilterArea;
      return matchesSearch && matchesArea;
    });
  }, [requests, searchTerm, globalFilterArea, canUserSeeRequest]);

  const handleDrop = async (e: React.DragEvent, targetStatus: Status) => {
    e.preventDefault();
    setDragOverColumn(null);
    const requestId = e.dataTransfer.getData('requestId');
    try {
        await updateStatus(requestId, targetStatus);
    } catch (err: any) {
        alert(`POLÍTICA DE NEGOCIO: ${err.message}`);
    }
  };

  const COLUMNS = [
    { title: 'Bandeja Central', status: Status.RECIBIDO, icon: <Inbox size={16} />, color: 'indigo' },
    { title: 'Derivación', status: Status.DERIVACION, icon: <GitPullRequest size={16} />, color: 'orange' },
    { title: 'Ejecución', status: Status.EJECUCION, icon: <PlayCircle size={16} />, color: 'amber' },
    { title: 'Finalizado', status: Status.FINALIZADO, icon: <CheckCircle2 size={16} />, color: 'emerald' }
  ];

  return (
    <div className="flex flex-col h-full">
      <div className="px-8 py-4 flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white border-b border-slate-200">
          <div className="flex items-center gap-4">
             <h2 className="text-[11px] font-black text-slate-400 uppercase tracking-widest">
                {activeRole} - Tablero de Control
             </h2>
             <span className="bg-slate-100 text-slate-500 px-3 py-1 rounded-full text-[10px] font-bold">
                {filteredRequests.length} ACTIVOS
             </span>
          </div>

          <div className="flex items-center gap-4">
             <div className="relative min-w-[300px]">
                <Search size={14} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-400"/>
                <input 
                    type="text" 
                    value={searchTerm} 
                    onChange={(e) => setSearchTerm(e.target.value)} 
                    placeholder="Filtrar por ID o Asunto..." 
                    className="w-full pl-10 pr-4 py-2 text-xs font-medium bg-slate-50 border border-slate-200 rounded-xl focus:bg-white outline-none"
                />
             </div>

             {(activeRole === 'SUPERADMIN' || activeRole === 'ADMIN') && (
                <div className="relative">
                    <select 
                        value={globalFilterArea} 
                        onChange={(e) => setGlobalFilterArea(e.target.value as Area | 'ALL')} 
                        className="pl-4 pr-10 py-2 text-xs font-bold bg-white border border-slate-200 rounded-xl appearance-none cursor-pointer outline-none"
                    >
                        <option value="ALL">Todas las Áreas</option>
                        {Object.values(Area).map(a => <option key={a} value={a}>{a}</option>)}
                    </select>
                    <ChevronDown size={14} className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none"/>
                </div>
             )}
          </div>
      </div>

      <div className="flex-1 overflow-x-auto overflow-y-hidden custom-scrollbar bg-slate-50/50">
          <div className="h-full flex px-8 py-8 gap-8 min-w-[1200px]">
              {COLUMNS.map((col) => {
                  if (col.status === Status.RECIBIDO && activeRole !== 'ADMIN' && activeRole !== 'SUPERADMIN') return null;

                  const items = filteredRequests.filter(r => r.status === col.status);
                  return (
                      <div 
                          key={col.status} 
                          className={`flex-1 flex flex-col min-w-[280px] max-w-[350px] rounded-[2rem] border-2 border-transparent transition-all ${dragOverColumn === col.status ? 'bg-indigo-50 border-indigo-200 border-dashed' : ''}`} 
                          onDragOver={(e) => { e.preventDefault(); setDragOverColumn(col.status); }} 
                          onDragLeave={() => setDragOverColumn(null)} 
                          onDrop={(e) => handleDrop(e, col.status)}
                      >
                          <div className={`flex items-center justify-between px-6 py-4 bg-white border border-slate-100 rounded-2xl mb-4 shadow-sm text-[10px] font-black uppercase tracking-widest text-${col.color}-600`}>
                              <div className="flex items-center gap-3">{col.icon}{col.title}</div>
                              <span className="opacity-40">{items.length}</span>
                          </div>

                          <div className="flex-1 overflow-y-auto px-1 pb-10 custom-scrollbar space-y-3">
                              {items.map(req => <RequestCard key={req.id} data={req} />)}
                          </div>
                      </div>
                  )
              })}
          </div>
      </div>
    </div>
  );
};

