export enum Status {
  RECIBIDO = 'Recibido',      // Bandeja de Entrada Central (Admin)
  DERIVACION = 'En Derivación', // Asignado a un Área (Jefe de Área)
  EJECUCION = 'En Ejecución',   // En trabajo activo por un Analista
  FINALIZADO = 'Finalizado'     // Requerimiento resuelto y auditado
}

export enum Priority {
  HIGH = 'Alta',
  MEDIUM = 'Media',
  LOW = 'Baja'
}

export type UserStatus = 'ACTIVE' | 'INACTIVE';

export interface User {
  id: string;
  name: string;
  email: string;
  role: UserRole;
  area?: Area; 
  password?: string;
  status?: UserStatus;
  joinedAt?: string;
}

export interface LogEntry {
  id: string;
  timestamp: string;
  message: string;
  actor: string;
  role: UserRole;
}

export interface RequestCard {
  id: string;
  title: string;
  detail: string;
  requester: string;
  area: Area;
  status: Status;
  priority: Priority;
  responsibleHead: string; 
  assignedAnalyst?: string; 
  logs: LogEntry[];
  createdAt: string;
  lastUpdated: string;
  finishedAt?: string;
  isReturned?: boolean; 
}

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { User, RequestCard, Status, Priority, Area, UserRole, LogEntry } from '../types';
import { AREA_HEADS } from '../constants';
import { db } from '../services/storage';

interface SisreqContextType {
  currentUser: User | null;
  users: User[];
  requests: RequestCard[];
  isAuthenticated: boolean;
  isLoading: boolean;
  activeRole: UserRole | null;
  globalFilterArea: Area | 'ALL';
  selectedRequestId: string | null;

  login: (user: User) => void;
  logout: () => void;
  setActiveRole: (role: UserRole) => void;
  addUser: (name: string, email: string, role: UserRole, password: string, area?: Area) => Promise<void>;
  updateUser: (updatedUser: User) => Promise<void>;

  setSelectedRequestId: (id: string | null) => void;
  setGlobalFilterArea: (area: Area | 'ALL') => void;
  addRequest: (title: string, detail: string, area: Area, priority: Priority, requester: string) => Promise<void>;
  updateStatus: (id: string, newStatus: Status) => Promise<void>;
  returnRequest: (id: string, reason: string) => Promise<void>;
  assignAnalyst: (id: string, analystName: string) => Promise<void>;
  addLog: (id: string, message: string) => Promise<void>;
  updateRequestDetails: (id: string, title: string, detail: string) => Promise<void>;
  deleteRequest: (id: string) => Promise<void>;

  canUserTransition: (request: RequestCard, targetStatus: Status) => { allowed: boolean; reason?: string };
  canUserSeeRequest: (request: RequestCard) => boolean;
}

const SisreqContext = createContext<SisreqContextType | undefined>(undefined);

const genId = (p: string) => `${p}-${Math.random().toString(36).substr(2, 9)}`;

export const SisreqProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [requests, setRequests] = useState<RequestCard[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeRole, setActiveRole] = useState<UserRole | null>(null);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [globalFilterArea, setGlobalFilterArea] = useState<Area | 'ALL'>('ALL');
  const [selectedRequestId, setSelectedRequestId] = useState<string | null>(null);

  useEffect(() => {
    const initializeSystem = async () => {
      try {
        await db.init();
        const [loadedUsers, loadedRequests] = await Promise.all([
          db.getUsers(),
          db.getRequests()
        ]);
        setUsers(loadedUsers);
        // Ordenamiento por actividad reciente (UX de alta disponibilidad)
        setRequests(loadedRequests.sort((a, b) => 
          new Date(b.lastUpdated || b.createdAt).getTime() - new Date(a.lastUpdated || a.createdAt).getTime()
        ));
      } catch (error) {
        console.error("CRITICAL: SISREQ Storage Layer Failure", error);
      } finally {
        setIsLoading(false);
      }
    };
    initializeSystem();
  }, []);

  const login = (user: User) => {
    setCurrentUser(user);
    setActiveRole(user.role);
    setIsAuthenticated(true);
    // Auto-calibración de vista según rol y área
    if (user.role === UserRole.ADMIN || user.role === UserRole.SUPERADMIN) {
      setGlobalFilterArea('ALL');
    } else {
      setGlobalFilterArea(user.area as Area);
    }
  };

  const logout = () => {
    setIsAuthenticated(false);
    setCurrentUser(null);
    setActiveRole(null);
    setSelectedRequestId(null);
  };

  /**
   * MOTOR DE POLÍTICAS DE VISIBILIDAD
   * Asegura que los usuarios técnicos solo operen en su jurisdicción.
   */
  const canUserSeeRequest = useCallback((req: RequestCard): boolean => {
    if (!currentUser || !activeRole) return false;

    // SuperAdmin y Admin Central poseen visibilidad total
    if (activeRole === UserRole.SUPERADMIN || activeRole === UserRole.ADMIN) return true;

    // Jefes y Analistas: Solo ven su Área y tickets que ya han salido de la Bandeja Central
    const isSameArea = req.area === currentUser.area;
    const isOutOfCentral = req.status !== Status.RECIBIDO;

    return isSameArea && isOutOfCentral;
  }, [currentUser, activeRole]);

  /**
   * MOTOR DE TRANSICIONES (MAQUINA DE ESTADOS)
   * Valida la coherencia del flujo de trabajo antes de cualquier cambio.
   */
  const canUserTransition = useCallback((req: RequestCard, target: Status): { allowed: boolean; reason?: string } => {
    if (!currentUser || !activeRole) return { allowed: false, reason: 'Sesión no identificada.' };
    if (req.status === target) return { allowed: true };

    // SuperAdmin: Bypass para correcciones de auditoría
    if (activeRole === UserRole.SUPERADMIN) return { allowed: true };

    // Inmutabilidad de tickets finalizados
    if (req.status === Status.FINALIZADO) {
      return { allowed: false, reason: 'Solo Auditoría Superior puede reabrir requerimientos cerrados.' };
    }

    switch (activeRole) {
      case UserRole.ADMIN:
        // El Admin Central solo puede mover de RECIBIDO a DERIVACION
        if (req.status === Status.RECIBIDO && target === Status.DERIVACION) return { allowed: true };
        return { allowed: false, reason: 'Labor administrativa limitada a la derivación inicial.' };

      case UserRole.HEAD:
        if (req.area !== currentUser.area) return { allowed: false, reason: 'Jurisdicción ajena.' };

        // DERIVACION -> EJECUCION (Requiere Analista Asignado)
        if (req.status === Status.DERIVACION && target === Status.EJECUCION) {
          if (!req.assignedAnalyst) return { allowed: false, reason: 'Debe asignar un analista antes de iniciar la ejecución.' };
          return { allowed: true };
        }
        // EJECUCION -> FINALIZADO
        if (req.status === Status.EJECUCION && target === Status.FINALIZADO) return { allowed: true };

        return { allowed: false, reason: 'Transición no permitida para el rol de Jefatura en este estado.' };

      case UserRole.ANALYST:
        if (req.area !== currentUser.area) return { allowed: false, reason: 'Jurisdicción ajena.' };
        // El analista solo puede mover a FINALIZADO
        if (req.status === Status.EJECUCION && target === Status.FINALIZADO) return { allowed: true };
        return { allowed: false, reason: 'El analista solo puede cerrar requerimientos en ejecución activa.' };

      default:
        return { allowed: false, reason: 'Rol no facultado para cambios de estado.' };
    }
  }, [currentUser, activeRole]);

  // --- OPERACIONES DE REQUERIMIENTO ---

  const addRequest = async (title: string, detail: string, area: Area, priority: Priority, requester: string) => {
    const now = new Date().toISOString();
    const newReq: RequestCard = {
      id: genId('REQ'),
      title,
      detail,
      area,
      status: Status.RECIBIDO,
      priority,
      requester,
      responsibleHead: AREA_HEADS[area],
      createdAt: now,
      lastUpdated: now,
      logs: [{
        id: genId('LOG'),
        timestamp: now,
        message: 'APERTURA: Registro formal de requerimiento en sistema',
        actor: currentUser?.name || 'Sistema',
        role: activeRole || UserRole.ADMIN
      }]
    };
    await db.saveRequest(newReq);
    setRequests(prev => [newReq, ...prev]);
  };

  const updateStatus = async (id: string, newStatus: Status) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const validation = canUserTransition(req, newStatus);
    if (!validation.allowed) throw new Error(validation.reason);

    const now = new Date().toISOString();
    const isReturningToCentral = newStatus === Status.RECIBIDO;

    const updated: RequestCard = {
      ...req,
      status: newStatus,
      lastUpdated: now,
      finishedAt: newStatus === Status.FINALIZADO ? now : req.finishedAt,
      // Limpieza de datos en retorno a central
      assignedAnalyst: isReturningToCentral ? undefined : req.assignedAnalyst,
      isReturned: isReturningToCentral ? true : (newStatus === Status.DERIVACION ? false : req.isReturned),
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: `TRANSICIÓN: Cambio de fase operativa a [${newStatus.toUpperCase()}]`,
        actor: currentUser.name,
        role: activeRole
      }]
    };

    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const returnRequest = async (id: string, reason: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      status: Status.RECIBIDO,
      isReturned: true,
      assignedAnalyst: undefined,
      lastUpdated: now,
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: `DEVOLUCIÓN A CENTRAL: ${reason}`,
        actor: currentUser.name,
        role: activeRole
      }]
    };

    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const assignAnalyst = async (id: string, analystName: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      assignedAnalyst: analystName,
      lastUpdated: now,
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: `ASIGNACIÓN: Personal técnico [${analystName}] designado responsable`,
        actor: currentUser.name,
        role: activeRole
      }]
    };

    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const addLog = async (id: string, message: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      lastUpdated: now,
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message,
        actor: currentUser.name,
        role: activeRole
      }]
    };
    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const updateRequestDetails = async (id: string, title: string, detail: string) => {
    const req = requests.find(r => r.id === id);
    if (!req || !currentUser || !activeRole) return;

    const now = new Date().toISOString();
    const updated: RequestCard = {
      ...req,
      title,
      detail,
      lastUpdated: now,
      logs: [...req.logs, {
        id: genId('LOG'),
        timestamp: now,
        message: 'EDICIÓN: Actualización de metadatos del ticket',
        actor: currentUser.name,
        role: activeRole
      }]
    };
    await db.saveRequest(updated);
    setRequests(prev => prev.map(r => r.id === id ? updated : r));
  };

  const deleteRequest = async (id: string) => {
    if (activeRole !== UserRole.SUPERADMIN) return;
    await db.deleteRequest(id);
    setRequests(prev => prev.filter(r => r.id !== id));
  };

  const addUser = async (name: string, email: string, role: UserRole, pass: string, area?: Area) => {
    const newUser: User = {
      id: genId('U'),
      name,
      email,
      role,
      area,
      password: pass,
      status: 'ACTIVE',
      joinedAt: new Date().toISOString()
    };
    await db.saveUser(newUser);
    setUsers(prev => [...prev, newUser]);
  };

  const updateUser = async (u: User) => {
    await db.saveUser(u);
    setUsers(prev => prev.map(o => o.id === u.id ? u : o));
    if (currentUser?.id === u.id) setCurrentUser(u);
  };

  return (
    <SisreqContext.Provider value={{
      currentUser, users, requests, isAuthenticated, isLoading, activeRole, globalFilterArea, selectedRequestId,
      login, logout, setActiveRole, addUser, updateUser,
      setSelectedRequestId, setGlobalFilterArea, addRequest, updateStatus, returnRequest, assignAnalyst, addLog, updateRequestDetails, deleteRequest,
      canUserTransition, canUserSeeRequest
    }}>
      {children}
    </SisreqContext.Provider>
  );
};

export const useSisreq = () => {
  const context = useContext(SisreqContext);
  if (context === undefined) throw new Error('useSisreq must be used within a SisreqProvider');
  return context;
};

import React, { useState, useMemo } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { RequestCard } from './RequestCard';
import { Status, Area, UserRole } from '../types';
import { Search, Inbox, GitPullRequest, PlayCircle, CheckCircle2, ChevronDown } from 'lucide-react';

export const Board: React.FC = () => {
  const { requests, updateStatus, globalFilterArea, setGlobalFilterArea, activeRole, canUserSeeRequest } = useSisreq();
  const [dragOverColumn, setDragOverColumn] = useState<Status | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  const filteredRequests = useMemo(() => {
    return requests.filter(req => {
      if (!canUserSeeRequest(req)) return false;

      const term = searchTerm.toLowerCase();
      const matchesSearch = searchTerm === '' || 
          req.title.toLowerCase().includes(term) ||
          req.id.toLowerCase().includes(term) ||
          req.requester.toLowerCase().includes(term) ||
          (req.assignedAnalyst && req.assignedAnalyst.toLowerCase().includes(term));

      const matchesArea = globalFilterArea === 'ALL' || req.area === globalFilterArea;
      return matchesSearch && matchesArea;
    });
  }, [requests, searchTerm, globalFilterArea, canUserSeeRequest]);

  const handleDrop = async (e: React.DragEvent, targetStatus: Status) => {
    e.preventDefault();
    setDragOverColumn(null);
    const requestId = e.dataTransfer.getData('requestId');
    try {
        await updateStatus(requestId, targetStatus);
    } catch (err: any) {
        // Alerta de negocio coherente
        alert(`SISREQ - RESTRICCIÓN DE FLUJO: ${err.message}`);
    }
  };

  const COLUMNS = [
    { title: 'Bandeja Central', status: Status.RECIBIDO, icon: <Inbox size={16} />, color: 'indigo' },
    { title: 'Derivación', status: Status.DERIVACION, icon: <GitPullRequest size={16} />, color: 'orange' },
    { title: 'Ejecución', status: Status.EJECUCION, icon: <PlayCircle size={16} />, color: 'amber' },
    { title: 'Finalizado', status: Status.FINALIZADO, icon: <CheckCircle2 size={16} />, color: 'emerald' }
  ];

  return (
    <div className="flex flex-col h-full bg-[#F8FAFC]">
      <div className="px-8 py-5 flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white border-b border-slate-200/60 shadow-sm z-10">
          <div className="flex items-center gap-5">
             <div className="flex flex-col">
                 <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] leading-none mb-1.5">
                    Modo Operativo: <span className="text-indigo-600">{activeRole}</span>
                 </h2>
                 <div className="flex items-center gap-2">
                    <span className="text-lg font-black text-slate-800 tracking-tight">Tablero de Control</span>
                    <span className="bg-slate-100 text-slate-500 px-3 py-0.5 rounded-full text-[10px] font-black border border-slate-200">
                        {filteredRequests.length} TICKETS
                    </span>
                 </div>
             </div>
          </div>

          <div className="flex items-center gap-4">
             <div className="relative min-w-[320px]">
                <Search size={14} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300"/>
                <input 
                    type="text" 
                    value={searchTerm} 
                    onChange={(e) => setSearchTerm(e.target.value)} 
                    placeholder="Buscar por ID, Asunto o Solicitante..." 
                    className="w-full pl-11 pr-4 py-2.5 text-xs font-semibold bg-slate-50 border border-slate-200 rounded-xl focus:bg-white focus:ring-4 focus:ring-indigo-500/5 focus:border-indigo-400 outline-none transition-all placeholder:text-slate-300"
                />
             </div>

             {(activeRole === UserRole.SUPERADMIN || activeRole === UserRole.ADMIN) && (
                <div className="relative">
                    <select 
                        value={globalFilterArea} 
                        onChange={(e) => setGlobalFilterArea(e.target.value as Area | 'ALL')} 
                        className="pl-4 pr-10 py-2.5 text-xs font-black bg-white border border-slate-200 rounded-xl appearance-none cursor-pointer outline-none focus:border-indigo-400 transition-all uppercase tracking-widest text-slate-600"
                    >
                        <option value="ALL">Todas las Áreas</option>
                        {Object.values(Area).map(a => <option key={a} value={a}>{a}</option>)}
                    </select>
                    <ChevronDown size={14} className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none"/>
                </div>
             )}
          </div>
      </div>

      <div className="flex-1 overflow-x-auto overflow-y-hidden custom-scrollbar">
          <div className="h-full flex px-8 py-10 gap-8 min-w-[1300px]">
              {COLUMNS.map((col) => {
                  // Validación de visibilidad de columna según rol
                  if (col.status === Status.RECIBIDO && activeRole !== UserRole.ADMIN && activeRole !== UserRole.SUPERADMIN) return null;

                  const items = filteredRequests.filter(r => r.status === col.status);
                  const isDragActive = dragOverColumn === col.status;

                  return (
                      <div 
                          key={col.status} 
                          className={`flex-1 flex flex-col min-w-[300px] max-w-[380px] rounded-[2.5rem] transition-all duration-300 ${isDragActive ? 'bg-indigo-50/50 ring-2 ring-indigo-200 ring-dashed' : 'bg-transparent'}`} 
                          onDragOver={(e) => { e.preventDefault(); setDragOverColumn(col.status); }} 
                          onDragLeave={() => setDragOverColumn(null)} 
                          onDrop={(e) => handleDrop(e, col.status)}
                      >
                          <div className={`flex items-center justify-between px-6 py-4 bg-white border border-slate-100 rounded-2xl mb-6 shadow-sm`}>
                              <div className="flex items-center gap-3">
                                  <div className={`p-2 rounded-lg bg-${col.color}-50 text-${col.color}-600`}>{col.icon}</div>
                                  <span className={`text-[10px] font-black uppercase tracking-widest text-${col.color}-700`}>{col.title}</span>
                              </div>
                              <span className="bg-slate-50 text-slate-400 px-2.5 py-1 rounded-lg text-[10px] font-black border border-slate-100">{items.length}</span>
                          </div>

                          <div className="flex-1 overflow-y-auto px-1 pb-20 custom-scrollbar space-y-4">
                              {items.map(req => <RequestCard key={req.id} data={req} />)}
                              {items.length === 0 && (
                                  <div className="flex flex-col items-center justify-center h-40 border-2 border-dashed border-slate-200/50 rounded-[2rem] text-slate-300">
                                      <div className="mb-2 opacity-40">{col.icon}</div>
                                      <p className="text-[10px] font-bold uppercase tracking-widest">Sin Pendientes</p>
                                  </div>
                              )}
                          </div>
                      </div>
                  )
              })}
          </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { STATUS_BADGE_COLORS, PRIORITY_STYLES } from '../constants';
import { UserRole, Status } from '../types';
import { 
    X, User, Building, Clock, Save, Send, MessageSquare,
    RotateCcw, Sparkles, CheckCircle2, Hash, PlayCircle, Trash2,
    ShieldAlert, UserCheck, History, ClipboardList, PenTool
} from 'lucide-react';

export const RequestDetailModal: React.FC = () => {
  const { 
    selectedRequestId, 
    setSelectedRequestId, 
    requests, 
    currentUser, 
    updateStatus, 
    deleteRequest,
    returnRequest, 
    assignAnalyst,
    updateRequestDetails,
    addLog,
    users,
    activeRole,
    canUserTransition
  } = useSisreq();

  const [returnReason, setReturnReason] = useState('');
  const [showReturnInput, setShowReturnInput] = useState(false);
  const [showAnalystSelect, setShowAnalystSelect] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editTitle, setEditTitle] = useState('');
  const [editDetail, setEditDetail] = useState('');
  const [newComment, setNewComment] = useState('');
  const [actionError, setActionError] = useState<string | null>(null);

  const data = requests.find(r => r.id === selectedRequestId);

  useEffect(() => {
     if (data) {
        setEditTitle(data.title);
        setEditDetail(data.detail);
        setIsEditing(false);
        setShowReturnInput(false);
        setShowAnalystSelect(false);
        setNewComment('');
        setActionError(null);
     }
  }, [selectedRequestId, data]);

  if (!selectedRequestId || !data || !currentUser) return null;

  const handleClose = () => setSelectedRequestId(null);
  const isFinalized = data.status === Status.FINALIZADO;

  const handleTransition = async (targetStatus: Status) => {
    setActionError(null);
    try {
        await updateStatus(data.id, targetStatus);
    } catch (e: any) {
        setActionError(e.message);
    }
  };

  const handleReturnSubmit = async () => {
    if (returnReason.trim()) {
      try {
        await returnRequest(data.id, returnReason);
        setShowReturnInput(false);
        setReturnReason('');
      } catch (e: any) {
        setActionError(e.message);
      }
    }
  };

  const handleAssignAnalyst = (analystName: string) => {
    assignAnalyst(data.id, analystName);
    setShowAnalystSelect(false);
  };

  const handleSaveChanges = async () => {
    if (editTitle.trim() && editDetail.trim()) {
        await updateRequestDetails(data.id, editTitle, editDetail);
        setIsEditing(false);
    }
  };

  const handleAddComment = async () => {
    if (newComment.trim()) {
        await addLog(data.id, `MENSAJE TÉCNICO: ${newComment}`);
        setNewComment('');
    }
  };

  const availableAssignees = users.filter(u => 
    (u.role === UserRole.ANALYST || u.role === UserRole.HEAD) && 
    u.area === data.area &&
    (u.status === 'ACTIVE' || !u.status)
  );

  const canDeriveUI = canUserTransition(data, Status.DERIVACION).allowed;
  const canExecuteUI = canUserTransition(data, Status.EJECUCION).allowed;
  const canFinalizeUI = canUserTransition(data, Status.FINALIZADO).allowed;
  const canEditUI = activeRole === UserRole.ADMIN || activeRole === UserRole.SUPERADMIN;

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-900/80 backdrop-blur-md transition-opacity" onClick={handleClose}></div>

      <div className={`relative bg-white rounded-[3rem] shadow-2xl w-full max-w-2xl max-h-[94vh] flex flex-col overflow-hidden animate-in fade-in zoom-in-95 duration-300 border border-slate-200 border-t-[14px] ${isFinalized ? 'border-emerald-500' : 'border-indigo-600'}`}>

        {/* Encabezado Profesional */}
        <div className="bg-slate-50 border-b border-slate-100 px-8 py-7 flex justify-between items-center shrink-0">
          <div className="flex items-center gap-5 min-w-0">
             <div className={`p-4 rounded-2xl text-white shrink-0 shadow-lg ${isFinalized ? 'bg-emerald-600' : 'bg-slate-800'}`}>
                {isFinalized ? <CheckCircle2 size={24} strokeWidth={2.5}/> : <ClipboardList size={24} strokeWidth={2.5} />}
             </div>
             <div className="min-w-0">
                <div className="flex items-center gap-2 mb-1.5">
                    <span className={`px-3 py-1 rounded-lg text-[10px] font-black uppercase tracking-[0.15em] shadow-sm ring-1 ring-black/5 ${STATUS_BADGE_COLORS[data.status]}`}>
                        {data.status}
                    </span>
                    <span className="text-[10px] text-slate-400 font-mono font-black bg-white px-2 py-1 rounded border border-slate-100 flex items-center gap-1">
                        <Hash size={10} className="opacity-40"/>{data.id.split('-')[1].toUpperCase()}
                    </span>
                </div>
                {isEditing ? (
                    <input 
                        value={editTitle}
                        onChange={e => setEditTitle(e.target.value)}
                        className="text-xl font-black text-slate-900 w-full bg-white border-b-2 border-indigo-500 outline-none uppercase tracking-tight"
                    />
                ) : (
                    <h2 className="text-xl font-black text-slate-900 truncate uppercase tracking-tight leading-none">{data.title}</h2>
                )}
             </div>
          </div>
          <button onClick={handleClose} className="p-3 text-slate-300 hover:text-slate-900 hover:bg-white rounded-full transition-all border border-transparent hover:border-slate-100">
            <X size={24} />
          </button>
        </div>

        {/* Cuerpo del Expediente */}
        <div className="flex-1 overflow-y-auto p-10 space-y-12 bg-white custom-scrollbar">

            <div className="space-y-4">
                <div className="flex items-center justify-between">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2.5">
                        <PenTool size={14} className="text-indigo-500"/> Descripción Técnica
                    </label>
                    {canEditUI && !isEditing && (
                        <button onClick={() => setIsEditing(true)} className="text-[10px] font-black text-indigo-600 uppercase hover:underline">Editar Expediente</button>
                    )}
                </div>
                {isEditing ? (
                    <textarea 
                        value={editDetail}
                        onChange={e => setEditDetail(e.target.value)}
                        className="w-full bg-slate-50 border-2 border-indigo-100 p-6 rounded-[2.5rem] text-sm text-slate-700 leading-relaxed outline-none min-h-[160px] font-medium shadow-inner"
                    />
                ) : (
                    <div className="bg-slate-50/50 p-8 rounded-[2.5rem] border border-slate-100 italic text-slate-600 text-sm leading-relaxed shadow-inner">
                        "{data.detail}"
                    </div>
                )}
                {isEditing && (
                    <div className="flex justify-end gap-4 pt-2">
                        <button onClick={() => setIsEditing(false)} className="px-5 py-2.5 text-[10px] font-black text-slate-400 uppercase tracking-widest hover:text-slate-600">Cancelar</button>
                        <button onClick={handleSaveChanges} className="bg-indigo-600 text-white px-8 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest shadow-xl shadow-indigo-100 flex items-center gap-2.5 active:scale-95 transition-all">
                            <Save size={16}/> Guardar Cambios
                        </button>
                    </div>
                )}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="p-6 bg-white border border-slate-100 rounded-[2rem] shadow-sm group hover:border-indigo-100 transition-all">
                    <p className="text-[10px] font-black text-slate-400 uppercase mb-3 flex items-center gap-2.5">
                        <User size={14}/> Solicitante
                    </p>
                    <p className="text-[14px] font-black text-slate-800 truncate uppercase tracking-tight">{data.requester}</p>
                </div>
                <div className="p-6 bg-white border border-slate-100 rounded-[2rem] shadow-sm group hover:border-indigo-100 transition-all">
                    <p className="text-[10px] font-black text-slate-400 uppercase mb-3 flex items-center gap-2.5">
                        <Building size={14}/> Unidad de Gestión
                    </p>
                    <p className="text-[14px] font-black text-slate-800 uppercase tracking-tight">{data.area}</p>
                </div>
            </div>

            <div className="p-8 bg-indigo-50/50 border border-indigo-100 rounded-[3rem] flex flex-col md:flex-row items-center gap-8 shadow-inner">
                <div className={`w-16 h-16 rounded-2xl flex items-center justify-center text-white font-black text-xl shadow-lg ${data.assignedAnalyst ? 'bg-indigo-600' : 'bg-slate-300'}`}>
                    {data.assignedAnalyst ? data.assignedAnalyst.substring(0,2).toUpperCase() : '?'}
                </div>
                <div className="flex-1 text-center md:text-left">
                    <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-1">Responsable Técnico de Ejecución</p>
                    <p className={`text-lg font-black uppercase tracking-tight ${data.assignedAnalyst ? 'text-indigo-900' : 'text-slate-400 italic'}`}>
                        {data.assignedAnalyst || 'Personal no asignado'}
                    </p>
                </div>
                {activeRole === UserRole.HEAD && data.status === Status.DERIVACION && (
                    <div className="relative">
                        <button 
                            onClick={() => setShowAnalystSelect(!showAnalystSelect)}
                            className="bg-white border-2 border-indigo-200 text-indigo-600 px-8 py-3.5 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-indigo-600 hover:text-white transition-all shadow-md active:scale-95"
                        >
                            {data.assignedAnalyst ? 'Reasignar' : 'Nombrar Responsable'}
                        </button>
                        {showAnalystSelect && (
                            <div className="absolute bottom-full right-0 mb-4 w-72 bg-white border border-slate-200 shadow-2xl rounded-[2rem] p-3 z-[70] animate-in slide-in-from-bottom-4">
                                <div className="p-4 border-b border-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest">Personal habilitado en {data.area}</div>
                                {availableAssignees.map(u => (
                                    <button 
                                        key={u.id} 
                                        onClick={() => handleAssignAnalyst(u.name)} 
                                        className="w-full text-left px-5 py-4 hover:bg-indigo-50 rounded-2xl text-[12px] font-black text-slate-700 uppercase transition-all flex items-center gap-3"
                                    >
                                        <div className="w-2 h-2 rounded-full bg-indigo-400"></div>
                                        {u.name}
                                    </button>
                                ))}
                                {availableAssignees.length === 0 && <div className="p-6 text-[11px] italic text-slate-400 text-center font-bold">No hay analistas activos en esta unidad operativa</div>}
                            </div>
                        )}
                    </div>
                )}
            </div>

            <div className="space-y-8 pt-8 border-t border-slate-100">
                <div className="flex items-center justify-between">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2.5">
                        <History size={14}/> Bitácora de Auditoría (Logs Inmutables)
                    </label>
                    <span className="text-[9px] font-black text-slate-300 uppercase tracking-widest bg-slate-50 px-3 py-1.5 rounded-xl border border-slate-100">Integrity Check OK</span>
                </div>

                <div className="space-y-6">
                    <div className="flex gap-5">
                         <div className="w-12 h-12 rounded-2xl bg-slate-50 border border-slate-100 flex items-center justify-center text-slate-400 shrink-0 shadow-inner">
                            <MessageSquare size={20}/>
                         </div>
                         <div className="flex-1 flex gap-3">
                            <input 
                                value={newComment}
                                onChange={e => setNewComment(e.target.value)}
                                placeholder="Añadir nota técnica o instrucción operativa..."
                                className="flex-1 bg-slate-50 border border-slate-200 rounded-2xl px-6 text-xs font-bold focus:outline-none focus:ring-8 focus:ring-indigo-500/5 focus:border-indigo-400 shadow-inner"
                            />
                            <button 
                                onClick={handleAddComment}
                                disabled={!newComment.trim()}
                                className="bg-slate-900 text-white p-3.5 rounded-2xl disabled:opacity-20 hover:bg-slate-800 transition-all shadow-lg active:scale-95"
                            >
                                <Send size={20}/>
                            </button>
                         </div>
                    </div>

                    <div className="space-y-6 relative pl-6 border-l-2 border-slate-50 ml-6">
                        {[...data.logs].reverse().map((log) => (
                            <div key={log.id} className="relative">
                                <div className="absolute -left-[31px] top-4 w-4 h-4 rounded-full bg-slate-200 border-4 border-white group-first:bg-indigo-500"></div>
                                <div className="bg-slate-50/50 p-5 rounded-2xl border border-slate-100 hover:bg-white hover:shadow-sm transition-all">
                                    <div className="flex justify-between items-center mb-2">
                                        <div className="flex items-center gap-3">
                                            <span className="text-[11px] font-black text-slate-800 uppercase tracking-tight">{log.actor}</span>
                                            <span className="px-2 py-0.5 bg-slate-100 rounded-lg text-[8px] font-black text-slate-400 uppercase tracking-widest border border-slate-200">{log.role}</span>
                                        </div>
                                        <span className="text-[10px] text-slate-400 font-mono font-bold flex items-center gap-2">
                                            <Clock size={12} />
                                            {new Date(log.timestamp).toLocaleDateString()} {new Date(log.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                                        </span>
                                    </div>
                                    <p className="text-[12px] text-slate-600 font-bold uppercase tracking-tight leading-relaxed">{log.message}</p>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        </div>

        {/* Acciones de Pie de Expediente */}
        <div className="bg-white border-t border-slate-100 p-10 flex flex-col gap-6 shrink-0 z-20 shadow-[0_-10px_40px_rgba(0,0,0,0.03)]">
            {actionError && (
                <div className="bg-red-50 border border-red-100 p-5 rounded-2xl flex items-center gap-4 text-red-600 text-[11px] font-black uppercase tracking-widest animate-in slide-in-from-top-4 shadow-sm">
                    <ShieldAlert size={20}/> {actionError}
                </div>
            )}

            <div className="flex justify-between items-center gap-6">
                <div className="flex items-center gap-3">
                    {activeRole === UserRole.SUPERADMIN && (
                        <button 
                            onClick={() => { if(confirm('¿ELIMINAR REQUERIMIENTO DEL SISTEMA DE FORMA PERMANENTE?')) { deleteRequest(data.id); handleClose(); }}} 
                            className="p-4 text-red-400 hover:text-red-600 hover:bg-red-50 rounded-2xl transition-all border border-transparent hover:border-red-100"
                            title="Eliminar Expediente"
                        >
                            <Trash2 size={22}/>
                        </button>
                    )}

                    {(activeRole === UserRole.HEAD || activeRole === UserRole.SUPERADMIN || activeRole === UserRole.ADMIN) && data.status !== Status.RECIBIDO && data.status !== Status.FINALIZADO && (
                        <div className="flex items-center gap-3">
                            {showReturnInput ? (
                                <div className="flex items-center gap-3 bg-red-50 p-2 rounded-2xl border border-red-100 animate-in slide-in-from-left-6">
                                    <input 
                                        autoFocus
                                        value={returnReason}
                                        onChange={e => setReturnReason(e.target.value)}
                                        placeholder="Motivo de rechazo/devolución..."
                                        className="bg-white border border-red-200 px-5 py-3 rounded-xl text-[11px] font-bold text-red-900 outline-none w-64 shadow-inner"
                                    />
                                    <button onClick={handleReturnSubmit} className="bg-red-600 text-white px-6 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-red-700 active:scale-95 transition-all shadow-md">Confirmar Devolución</button>
                                    <button onClick={() => setShowReturnInput(false)} className="p-3 text-red-400 hover:text-red-600"><X size={20}/></button>
                                </div>
                            ) : (
                                <button 
                                    onClick={() => setShowReturnInput(true)} 
                                    className="px-8 py-4 rounded-2xl text-[11px] font-black text-red-600 border-2 border-red-100 hover:bg-red-50 transition-all uppercase tracking-widest flex items-center gap-3 active:scale-95"
                                >
                                    <RotateCcw size={16} strokeWidth={3}/> Retornar a Central
                                </button>
                            )}
                        </div>
                    )}
                </div>

                <div className="flex gap-4">
                    {canDeriveUI && (
                        <button 
                            onClick={() => handleTransition(Status.DERIVACION)} 
                            className="bg-indigo-600 text-white px-10 py-5 rounded-[2rem] text-[12px] font-black uppercase tracking-[0.2em] shadow-2xl shadow-indigo-200 hover:bg-indigo-700 active:scale-95 transition-all flex items-center gap-4 border border-indigo-700"
                        >
                            <UserCheck size={20}/> Derivar a Unidad Técnica
                        </button>
                    )}

                    {canExecuteUI && (
                        <button 
                            onClick={() => handleTransition(Status.EJECUCION)} 
                            className="bg-amber-500 text-white px-10 py-5 rounded-[2rem] text-[12px] font-black uppercase tracking-[0.2em] shadow-2xl shadow-amber-200 hover:bg-amber-600 active:scale-95 transition-all flex items-center gap-4 border border-amber-600"
                        >
                            <PlayCircle size={20}/> Iniciar Fase Ejecución
                        </button>
                    )}

                    {canFinalizeUI && (
                        <button 
                            onClick={() => handleTransition(Status.FINALIZADO)} 
                            className="bg-emerald-600 text-white px-10 py-5 rounded-[2rem] text-[12px] font-black uppercase tracking-[0.2em] shadow-2xl shadow-emerald-200 hover:bg-emerald-700 active:scale-95 transition-all flex items-center gap-4 border border-emerald-700"
                        >
                            <CheckCircle2 size={20} strokeWidth={3}/> Declarar Cumplimiento
                        </button>
                    )}

                    {isFinalized && activeRole === UserRole.SUPERADMIN && (
                        <button 
                            onClick={() => handleTransition(Status.RECIBIDO)} 
                            className="bg-slate-900 text-white px-10 py-5 rounded-[2rem] text-[12px] font-black uppercase tracking-[0.2em] shadow-2xl shadow-slate-200 hover:bg-slate-800 active:scale-95 transition-all flex items-center gap-4"
                        >
                            <Sparkles size={20}/> Reabrir para Auditoría Técnica
                        </button>
                    )}
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};
